const CREATURES = [{"id":"notice-00","title":"La Nyxie","sourceTitle":"","latin":"Lucifae Rosea Somniphage","subtitle":"La Mangeuse de Cauchemars","kind":"Esprit / hybride","filter":"esprit","files":[],"description":"Petite fée lumineuse qui dévore les cauchemars et les transforme en apaisement. Elle flotte silencieusement et attire par sa douceur et sa tendresse.","facts":{"taille":"Petite (fée dodue)","poids":"Léger / potelé et moelleux","habitat":"Chambres, lieux paisibles et sombres","origine":"Non spécifiée","status":"être"},"keywords":"nyxie lucifae rosea somniphage mangeuse cauchemars fée","longText":"Petite fée dodue lumineuse qui dévore les cauchemars et les transforme en apaisement. Flotte silencieusement, attire par douceur et tendresse. Sa présence signifie l’absence de cauchemars.","publishedFacts":{"taille":"Petite (fée dodue)","poids":"Léger / potelé et moelleux","habitat":"Chambres, lieux paisibles et sombres"},"summary":"Petite fée lumineuse, la Nyxie se nourrit des cauchemars et les transforme en apaisement. Elle flotte sans bruit et sa douceur attire ceux qui croisent son chemin."},{"id":"notice-01","title":"La Voltamite","sourceTitle":"","latin":"Formica Voltatica","subtitle":"L’Insecte Électrique","kind":"Terrestre","filter":"terrestre","files":[2],"description":"Petit insecte qui produit de faibles décharges électriques accélérant la décomposition du bois. Il joue un rôle de catalyseur écologique.","facts":{"taille":"1 à 2 cm","poids":"Quasi nul","habitat":"Bois pourrissant, branches fragilisées","status":"animal","classification":"1x"},"keywords":"voltamite formica voltatica insecte électrique","summary":"La Voltamite produit de faibles décharges électriques qui accélèrent la décomposition du bois. Ce petit insecte contribue ainsi à l’équilibre de son environnement."},{"id":"notice-02","title":"Le Morblin","sourceTitle":"","latin":"Morosus Blinnus","subtitle":"Shnouff / La Créature la Plus Ennuyeuse qui Soit","kind":"Terrestre","filter":"terrestre","files":[3],"description":"Petit être trapu et poilu, le Morblin passe ses journées à faire des gestes absurdes et suit les gens en silence. Il suffit de l’ignorer pour qu’il parte.","facts":{"taille":"40 cm","poids":"Environ 7 kg","habitat":"Jardins abandonnés, clairières, vieilles maisons","status":"être"},"keywords":"morblin morosus blinnus shnouff ennuyeuse","summary":"Le Morblin est un petit être trapu et poilu, solitaire et non agressif. Il suit les passants en silence et se livre à des gestes absurdes; l’ignorer suffit généralement à le faire partir."},{"id":"notice-03","title":"Le Tanuki","sourceTitle":"","latin":"Nyctereutes Tricksteris","subtitle":"Farces, Métamorphoses et Testicules Fantastiques","kind":"Terrestre","filter":"terrestre","files":[4],"description":"Canidé métamorphe légendaire japonais, le Tanuki trompe les humains pour s’amuser. Sa métamorphose est totale et ses testicules sont réputés magiques et multifonctions.","facts":{"origine":"Japon (légendaire)","habitat":"Forêts, lisières de villages, auberges","status":"animal","classification":"2x"},"keywords":"tanuki nyctereutes tricksteris farces métamorphoses japon","summary":"Le Tanuki est un canidé métamorphe légendaire du Japon, connu pour ses farces. Sa métamorphose est totale et ses testicules possèdent, selon les récits, de multiples propriétés magiques."},{"id":"notice-04","title":"Le Vespian","sourceTitle":"","latin":"Vespa Geometris","subtitle":"L'Architecte des Champs","kind":"Aérien","filter":"aerien","files":[5],"description":"Guêpe géante, le Vespian dessine des crop circles lors de sa parade nuptiale. Ses motifs géométriques marquent aussi son territoire.","facts":{"taille":"30 cm d’envergure","habitat":"Champs ouverts, prairies rurales","status":"animal","classification":"2x"},"keywords":"vespian vespa geometris architecte champs crop circles","summary":"Le Vespian est une guêpe géante qui dessine des crop circles comme rituel de séduction. Ses motifs géométriques servent à la parade nuptiale et marquent son territoire."},{"id":"notice-05","title":"Le Miragel","sourceTitle":"","latin":"Aves Glacialis","subtitle":"Le Colporteur de l'Hiver","kind":"Aérien","filter":"aerien","files":[6],"description":"Oiseau au plumage glacé, le Miragel voit ses plumes tombées se figer en glace éternelle. Ses plumes réfrigérantes sont très prisées en alchimie.","facts":{"taille":"86 cm long / 150 cm envergure","poids":"Environ 3,5 kg","origine":"Groenland","habitat":"Lacs gelés, climats extrêmes","status":"animal","classification":"2x"},"keywords":"miragel aves glacialis colporteur hiver groenland","longText":"**CARACTÉRISTIQUES BIOLOGIQUES**\nOiseau aquatique magique au plumage qui semble ciselé dans la glace. Chaque plume, translucide et lumineuse, révèle des nuances d’azur et de turquoise. Originaire du Groenland, il fréquente les lacs gelés. Pesant environ 3,5 kg pour 86 cm de long et une envergure de 150 cm.\n\n**COMPORTEMENT**\nDiscret et farouche. Les plumes tombées du Miragel se figent instantanément en glace éternelle. Malgré sa nature grégaire, il reste extrêmement farouche.\n\n**UTILISATION**\nLes plumes de Miragel sont prisées pour leurs propriétés magiques et alchimiques, notamment leur pouvoir réfrigérant exceptionnel.","publishedFacts":{"taille":"86 cm / 150 cm envergure","poids":"3,5 kg","origine":"Groenland","habitat":"Lacs gelés, climats extrêmes"},"summary":"Le Miragel est un oiseau au plumage de glace. Les plumes qu’il perd se figent en glace éternelle et sont recherchées pour leurs propriétés réfrigérantes en alchimie."},{"id":"notice-06","title":"Le Miravore","sourceTitle":"","latin":"Sericatus Mirabilis","subtitle":"Tisseur de Rêves","kind":"Terrestre","filter":"terrestre","files":[7],"description":"Chenille magique, le Miravore tisse dans l’air un fil irisé utilisé pour confectionner des vêtements enchantés. Elle ajuste la rigidité du fil selon l’usage.","facts":{"taille":"Petite (chenille)","habitat":"Bibliothèques, chambres de sorciers, attrape-rêves","status":"animal","classification":"2x"},"keywords":"miravore sericatus mirabilis tisseur rêves","summary":"Le Miravore est une chenille qui tisse un fil irisé magique dans l’air. Ce fil sert à fabriquer des vêtements enchantés, et la chenille peut en ajuster la rigidité selon l’usage."},{"id":"notice-07","title":"Le Lunavore","sourceTitle":"","latin":"Somnalis Aethera","subtitle":"Messager des Songes","kind":"Aérien","filter":"aerien","files":[8],"description":"Forme ailée du Miravore, le Lunavore produit une poussière de songes apaisante. Son cycle de sept vies rend sa poussière et sa soie très prisées.","facts":{"taille":"Grand papillon de nuit","habitat":"Bibliothèques, chambres endormies, pleine lune","status":"animal","classification":"2x"},"keywords":"lunavore somnalis aethera messager songes","summary":"Le Lunavore est la forme ailée du Miravore. Il produit une poussière de songes apaisante; son cycle de sept vies contribue à la rareté de sa poussière et de sa soie."},{"id":"notice-08","title":"L'Abysside","sourceTitle":"","latin":"Bivalvia Tenebrosa","subtitle":"Coquillage des Profondeurs","kind":"Terrestre","filter":"terrestre","files":[9],"description":"Coquillage luminescent des abysses, l’Abysside possède une nacre très recherchée. Il évite la lumière artificielle.","facts":{"origine":"Fosses marines profondes","habitat":"Rochers et coraux fossiles des abysses","status":"animal","classification":"1x"},"keywords":"abysside bivalvia tenebrosa coquillage profondeurs","summary":"L’Abysside est un coquillage luminescent des abysses dont la nacre est très recherchée. Sensible à la lumière artificielle, il se tient à l’écart des sources lumineuses."},{"id":"notice-09","title":"La Gyrbeline","sourceTitle":"","latin":"","subtitle":"Un éclat de curiosité sous un manteau de poussière","kind":"Esprit / hybride","filter":"esprit","files":[10],"description":"Petite créature curieuse, la Gyrbeline aide à retrouver les livres puis disparaît en nuage lumineux. Sa présence est considérée comme un bon présage.","facts":{"taille":"Petite (écureuil/souris)","habitat":"Bibliothèques anciennes, tours d’étude","status":"être","classification":"1x"},"keywords":"gyrbeline curiosité poussière bibliothèque","summary":"La Gyrbeline est une petite créature curieuse qui aide à retrouver les livres. Elle disparaît ensuite dans un nuage lumineux, signe de bonne augure."},{"id":"notice-10","title":"Le Chimelune","sourceTitle":"","latin":"","subtitle":"l’argenté des lacs","kind":"Aérien","filter":"aerien","files":[11],"description":"Créature aquatique argentée, le Chimelune se confond avec le reflet de la lune. Sa peau entre dans la composition d’onguents de vision nocturne.","facts":{"taille":"1 à 2 mètres","origine":"Lac Léman, Suisse","habitat":"Lacs profonds et rivières lentes d’Europe","status":"animal","classification":"3x"},"keywords":"chimelune argenté lacs léman suisse","summary":"Le Chimelune est une créature aquatique argentée qui se confond avec le reflet de la lune. Sa peau est utilisée dans des onguents favorisant la vision nocturne."},{"id":"notice-11","title":"Le Cormyrel","sourceTitle":"","latin":"","subtitle":"Le plongeur ailé","kind":"Aérien","filter":"aerien","files":[12],"description":"Oiseau sédentaire, le Cormyrel absorbe l’excès de magie des eaux puis le restitue. Sa présence indique un écosystème magique sain.","facts":{"habitat":"Lacs et eaux calmes","status":"animal","classification":"2x"},"keywords":"cormyrel plongeur ailé catalyseur","summary":"Le Cormyrel absorbe l’excès de magie présent dans les eaux et le restitue. Cet oiseau sédentaire est considéré comme le signe d’un écosystème magique sain."},{"id":"notice-12","title":"Le Criquet d’Onyx","sourceTitle":"","latin":"","subtitle":"Le Grincement Vivant","kind":"Terrestre","filter":"terrestre","files":[13],"description":"Le Criquet d’Onyx fait résonner son grincement magique à travers la pierre, au point de déranger les villages. Son exosquelette sert à fabriquer des bijoux réactifs.","facts":{"habitat":"Cavernes et zones pierreuses","status":"animal","classification":"3x"},"keywords":"criquet onyx grincement vivant","summary":"Le Criquet d’Onyx est un insecte dont le grincement magique résonne à travers la pierre. Son exosquelette est recherché pour la confection de bijoux réactifs."},{"id":"notice-13","title":"Le Grobullis","sourceTitle":"","latin":"Bubulapides languidus","subtitle":"Un poisson qui n’a pas envie de nager","kind":"Aquatique","filter":"aquatique","files":[14],"description":"Poisson extrêmement paresseux, le Grobullis communique par télépathie et pond des œufs convoités. Ceux-ci sont dangereux pour les baguettes.","facts":{"habitat":"Zones calmes et ensoleillées","status":"animal","classification":"3x"},"keywords":"grobullis bubulapides languidus poisson paresseux","summary":"Le Grobullis est un poisson extrêmement paresseux qui communique par télépathie. Ses œufs sont très recherchés, mais peuvent se révéler dangereux pour les baguettes."},{"id":"notice-14","title":"Le Mirlapin","sourceTitle":"","latin":"Leporis Cantarella","subtitle":"","kind":"Terrestre","filter":"terrestre","files":[15],"description":"Le Mirlapin est un lapin dont le chant cristallin favorise la croissance des plantes et apaise les conflits. Il disparaît en brume argentée.","facts":{"origine":"Ancienne magie druidique","habitat":"Forêts (Bois Chantant)","status":"animal","classification":"1x"},"keywords":"mirlapin leporis cantarella mélodieux","summary":"Le Mirlapin possède un chant cristallin qui favorise la croissance des plantes et apaise les conflits. Lorsqu’il disparaît, il se change en brume argentée."},{"id":"notice-15","title":"Le Spectrevrif","sourceTitle":"Le Spectrevif","latin":"","subtitle":"l’éthéré des sous-bois","kind":"Esprit / hybride","filter":"esprit","files":[16],"description":"Esprit animal, le Spectrevrif reflète une ou plusieurs âmes et peut guider ou hanter les vivants. Pour l’approcher, il faut imiter le cri de l’animal.","facts":{"taille":"Variable","poids":"Éthéré (quasi nul)","origine":"Âmes perdues","habitat":"Forêts anciennes, marais, rivières calmes","status":"esprits","classification":"3x"},"keywords":"spectrevif éthéré sous-bois esprit","summary":"Le Spectrevrif est un esprit animal errant lié à une ou plusieurs âmes. Il peut guider ou hanter ceux qu’il rencontre; l’imitation du cri de l’animal permet de l’approcher."},{"id":"notice-16","title":"Le Ténébris","sourceTitle":"","latin":"","subtitle":"L'Ombre des Forêts","kind":"Esprit / hybride","filter":"esprit","files":[17],"description":"Les Ténébris sont des ombres vivantes qui prennent l’apparence d’animaux. Elles apportent calme et fraîcheur et absorbent la peur.","facts":{"taille":"Variable","poids":"Éthéré (ombre)","habitat":"Forêts, clairières brumeuses","status":"esprits","classification":"2x"},"keywords":"ténébris ombre forêts","summary":"Les Ténébris prennent l’apparence d’animaux et vivent dans les forêts et les clairières brumeuses. Paisibles et protectrices, elles apportent calme et fraîcheur en absorbant la peur."},{"id":"notice-17","title":"Le Terragor","sourceTitle":"","latin":"Terragobrus Ferrovore","subtitle":"Dormeur Gris","kind":"Terrestre","filter":"terrestre","files":[18],"description":"Créature souterraine, le Terragor mange des minéraux qui renforcent sa carapace de cristaux. Il évite la lumière.","facts":{"habitat":"Galeries souterraines dans la pierre","status":"animal","classification":"3x"},"keywords":"terragor terragobrus ferrovore dormeur gris","summary":"Le Terragor se nourrit de minéraux, qu’il transforme en cristaux pour renforcer sa carapace. Cette créature souterraine solitaire évite la lumière."},{"id":"notice-18","title":"Le Marmolignon","sourceTitle":"","latin":"","subtitle":"Le Jardinier des Sous-Bois / pollinisateur naturel","kind":"Terrestre","filter":"terrestre","files":[19],"description":"Petite marmotte forestière à queue en forme de champignon luminescent, le Marmolignon disperse spores et graines. Les ronds de Marmolignon signalent sa présence.","facts":{"taille":"50 à 60 cm","poids":"3 à 5 kg","origine":"Pyrénées","habitat":"Zones montagneuses et forestières","status":"animal","classification":"2x"},"keywords":"marmolignon jardinier sous-bois pyrénées","summary":"Le Marmolignon est une petite créature forestière des Pyrénées, reconnaissable à sa queue en forme de champignon lumineux. Il disperse spores et graines dans les sous-bois."},{"id":"notice-19","title":"Le Luréliane","sourceTitle":"","latin":"Felisurus lunaris","subtitle":"Le Veilleur des Sous-Bois","kind":"Terrestre","filter":"terrestre","files":[20],"description":"Chat reptilien bioluminescent, le Luréliane protège les cultures en chassant les insectes. C’est un allié naturel des fermiers.","facts":{"taille":"Environ 40 cm","poids":"18 kg","habitat":"Sous-bois et terres agricoles","status":"animal","classification":"1x"},"keywords":"luréliane felisurus lunaris veilleur sous-bois","summary":"Le Luréliane est un chat reptilien lunaire qui chasse les insectes et protège les cultures. Sa présence bioluminescente en fait un allié apprécié des fermiers."},{"id":"notice-20","title":"Les Vorthans","sourceTitle":"","latin":"Vorthanus Marinus","subtitle":"Les Gardiens de l'Océan","kind":"Aquatique","filter":"aquatique","files":[21],"description":"Les Vorthans sont de puissants prédateurs marins à tête de crocodile qui défendent farouchement leur territoire. Leurs mâchoires peuvent broyer l’acier.","facts":{"taille":"2 à 10 mètres de long","origine":"Eaux d’Havengard","habitat":"Lacs, rivières et eaux côtières","status":"animal","classification":"3x"},"keywords":"vorthans vorthanus marinus gardiens océan havengard","summary":"Les Vorthans vivent dans les eaux d’Havengard et défendent leur territoire avec agressivité. Leur mâchoire puissante peut broyer l’acier."},{"id":"notice-21","title":"L'Aracnéa","sourceTitle":"L'Arachnéa","latin":"Aranea Tenebris","subtitle":"La Tisseuse des Horreurs","kind":"Terrestre","filter":"terrestre","files":[22],"description":"Araignée géante aux toiles argentées mortelles et au venin précieux, l’Aracnéa a un point faible sous l’abdomen.","facts":{"taille":"Jusqu’à 4 m d’envergure","poids":"Jusqu’à 200 kg","origine":"Bornéo","habitat":"Forêts, cavernes, ruines","status":"animal","classification":"5x"},"keywords":"arachnéa aranea tenebris tisseuse horreurs","summary":"L’Aracnéa est une araignée géante solitaire et territoriale. Ses toiles argentées sont mortelles, son venin est recherché et son point faible se trouve sous l’abdomen."},{"id":"notice-22","title":"Chantevoile","sourceTitle":"","latin":"Vox Umbrae","subtitle":"L'Ombre Mélodieuse","kind":"Esprit / hybride","filter":"esprit","files":[23],"description":"Entité spectrale, Chantevoile hypnotise par son chant et vide les âmes. Seule la magie positive peut la repousser.","facts":{"taille":"2 à 3 mètres","poids":"Aucune masse (spectral)","habitat":"Lieux sombres et brumeux","status":"non être","classification":"6x"},"keywords":"chantevoile vox umbrae ombre mélodieuse non-être","summary":"Chantevoile est une entité spectrale sombre et cruelle qui hypnotise ses victimes par son chant avant de vider leurs âmes. La magie positive est le seul moyen connu de la repousser."},{"id":"notice-23","title":"Kappa","sourceTitle":"","latin":"Homo Amphibious Cucumisphagus","subtitle":"Le Démon des Rivières","kind":"Esprit / hybride","filter":"esprit","files":[24],"description":"Créature japonaise, le Kappa noie les imprudents, mais respecte la politesse et adore les concombres. Il porte une calotte d’eau sur la tête.","facts":{"taille":"60 cm à 1 m","poids":"20 à 40 kg","origine":"Japon","habitat":"Rivières, lacs et marais calmes","status":"être","classification":"3x"},"keywords":"kappa homo amphibious cucumisphagus démon rivières japon","summary":"Le Kappa vit près des rivières et des marais. Imprévisible, il peut noyer les imprudents, mais respecte la politesse et raffole des concombres."},{"id":"notice-24","title":"Les Nocthréals","sourceTitle":"Les Nocthraals","latin":"Panthera Nocturna","subtitle":"Les Griffes de la Nuit","kind":"Aquatique","filter":"aquatique","files":[25],"description":"Fauve noir, le Nocthréal se nourrit de sang et disparaît dans les ténèbres. Il peut être lié par un pacte de sang.","facts":{"taille":"1,5 à 2 m de long / 1 m au garrot","poids":"50 à 70 kg","habitat":"Forêts épaisses, marais, montagnes","status":"animal","classification":"4x"},"keywords":"nocthraals panthera nocturna griffes nuit","summary":"Les Nocthréals sont des fauves nocturnes sanguinaires et imprévisibles. Ils se nourrissent de sang et peuvent être liés par un pacte de sang."},{"id":"notice-25","title":"Le Triton","sourceTitle":"","latin":"Triton Tenebris","subtitle":"L'Illusionniste silencieux","kind":"Aquatique","filter":"aquatique","files":[26],"description":"Prédateur amphibie, le Triton crée des illusions aquatiques pour piéger ses proies. Son mucus est toxique et il est faible hors de l’eau.","facts":{"taille":"1,80 à 2,50 m / envergure 3 m","habitat":"Lacs profonds, rivières, océans","status":"animal","classification":"4x"},"keywords":"triton triton tenebris illusionniste silencieux","summary":"Le Triton est un prédateur amphibie rusé et patient. Il attire ses proies à l’aide d’illusions aquatiques et supporte mal de quitter l’eau."},{"id":"notice-26","title":"Le Nagryel","sourceTitle":"Le Nagryl","latin":"Serpentis Divinæ Brumalis","subtitle":"Serpent des Brumes","kind":"Terrestre","filter":"terrestre","files":[27],"description":"Serpent géant des brumes, le Nagryel possède un venin qui provoque hallucinations et terreur. Il contrôle la brume; le feu constitue la meilleure défense.","facts":{"taille":"8 à 14 m","poids":"Environ 600 kg","origine":"Forêts anciennes d’Afrique (Ghana)","habitat":"Marécages et ruines enfouies","status":"animal","classification":"5x"},"keywords":"nagryl serpentis divinæ brumalis serpent brumes","longText":"**CARACTÉRISTIQUES BIOLOGIQUES**\nCréature reptilienne géante (8–14 m, 600 kg env.). Corps sombre, luisant, parfois irisé de vert ou de violet. Tête triangulaire surmontée de cornes osseuses. Crocs translucides qui sécrètent un venin fumant. Yeux qui perçoivent la chaleur.\n\n**DESCRIPTION ET CAPACITÉS**\nConsidéré par certains comme une malédiction née de la forêt. Sa peau absorbe la lumière et émet une vapeur spectrale. Attaques fulgurantes. Son venin provoque hallucinations et terreur avant la mort.\n\n**COMPORTEMENT**\nChaque Nagryl règne seul sur un territoire de plusieurs kilomètres. Il attire ou contrôle la brume. Le feu vif reste la meilleure protection connue.","publishedFacts":{"taille":"8 à 14 m","poids":"Environ 600 kg","origine":"Forêts anciennes d’Afrique (Ghana)","habitat":"Marécages et ruines enfouies"},"summary":"Le Nagryel est un serpent géant vivant dans les marécages et les ruines enfouies. Son venin provoque hallucinations et terreur, mais le feu constitue la meilleure défense contre lui."},{"id":"notice-27","title":"Givre Vivant","sourceTitle":"","latin":"","subtitle":"L'amas de glace qui respire la magie","kind":"Objet enchanté","filter":"artefact","files":[28],"description":"Le Givre Vivant est un amas de cristaux de glace animé par une conscience magique diffuse. Il peut se reformer et ses fragments sont utiles en alchimie.","facts":{"origine":"Fusion de cristaux de glace et mana","habitat":"Surfaces gelées et zones froides magiques","status":"non être","classification":"3x"},"keywords":"givre vivant amas glace magie élémental","summary":"Ce phénomène magique est composé de cristaux de glace animés par une conscience diffuse. Le Givre Vivant peut se reformer, et ses fragments servent en alchimie."},{"id":"notice-28","title":"Le Troll","sourceTitle":"","latin":"Lithofagus Vigilis","subtitle":"Le Veilleur des Montagnes","kind":"Terrestre","filter":"terrestre","files":[29],"description":"Créature de pierre, le Troll se pétrifie au soleil et rôde la nuit. Le feu empêche sa régénération.","facts":{"habitat":"Cols et sentiers escarpés, enfoui dans la roche","taille":"Massive (colosse)","origine":"Montagnes","status":"être","classification":"4x"},"keywords":"troll lithofagus vigilis veilleur montagnes","longText":"**DESCRIPTION GÉNÉRALE**\nCréature massive et solitaire, née des montagnes elles-mêmes. Sa peau bleu-gris se pétrifie au lever du soleil, le rendant indiscernable de la roche. La nuit, il rôde dans les cols et sentiers escarpés.\n\n**COMPORTEMENT**\nChaque Troll domine instinctivement un territoire précis. Il s’enfouit dans la roche et devient pratiquement indétectable lorsqu’il dort.\n\n**DANGERS**\nAttaque surtout la nuit. Le feu reste la meilleure défense : il empêche sa régénération.","publishedFacts":{"habitat":"Cols et sentiers escarpés, enfoui dans la roche"},"summary":"Le Troll est une créature massive et solitaire qui se cache dans la roche le jour et rôde la nuit. Pétrifié au soleil, il ne peut pas se régénérer si on l’attaque avec du feu."},{"id":"notice-29","title":"Le Volgriffe","sourceTitle":"","latin":"Volugrif Arboris","subtitle":"Un prédateur bariolé","kind":"Terrestre","filter":"terrestre","files":[30],"description":"Félin planeur aux couleurs vives, le Volgriffe chasse depuis les cimes et privilégie l’embuscade.","facts":{"origine":"Bassin amazonien","habitat":"Canopée des forêts tropicales","status":"animal","classification":"4x"},"keywords":"volgriffe volugrif arboris prédateur bariolé amazonie","summary":"Le Volgriffe vit dans la canopée des forêts tropicales. Ce félin planeur territorial et imprévisible chasse depuis les cimes, souvent par embuscade."},{"id":"notice-30","title":"Le Thérberos","sourceTitle":"Therberos","latin":"","subtitle":"Le Hurleur des Abîmes","kind":"Terrestre","filter":"terrestre","files":[31],"description":"Créature colossale à trois têtes, le Thérberos possède un rugissement qui rend fou. La Cendre de Fer ou les Clochettes d’Argent peuvent le déstabiliser.","facts":{"taille":"2,5 à 3 mètres","poids":"Plus d’une tonne","habitat":"Grottes profondes, ravins, ruines","status":"animal","classification":"5x"},"keywords":"therberos hurleur abîmes trois têtes","summary":"Le Thérberos est une créature colossale et destructrice à trois têtes. Son rugissement rend fou; la Cendre de Fer ou les Clochettes d’Argent peuvent le déstabiliser."},{"id":"notice-31","title":"L'Ophidrel","sourceTitle":"","latin":"","subtitle":"Le maître des reflets","kind":"Aquatique","filter":"aquatique","files":[32],"description":"Serpent élancé à peau translucide, l’Ophidrel se confond avec son environnement. Ses crocs sont utiles contre la Brume.","facts":{"taille":"2 à 4 mètres","origine":"Expériences des sorciers du CEM","habitat":"Lacs, rivières, marais brumeux, forêts","status":"animal","classification":"4x"},"keywords":"ophidrel maître reflets serpent","summary":"L’Ophidrel est un serpent magique solitaire, nocturne et territorial. Sa peau translucide le camoufle, et ses crocs peuvent être utilisés contre la Brume."},{"id":"notice-32","title":"Le Rôdard","sourceTitle":"Le Rodard","latin":"","subtitle":"Le Rôdeur Embrumé","kind":"Terrestre","filter":"terrestre","files":[33],"description":"Le Rôdard est un renard qui dégage une brume toxique et défend farouchement son territoire. Ses regroupements sont appelés « Nappe ».","facts":{"taille":"Environ 1,2 mètre de long","origine":"Écosse, Irlande, Pays de Galles","habitat":"Forêts denses, tourbières, lochs brumeux","status":"animal","classification":"4x"},"keywords":"rodard rôdeur embrumé renard écosse","summary":"Le Rôdard est un renard rusé et territorial qui se protège grâce à une brume toxique. Les regroupements de plusieurs Rôdards sont appelés des « Nappes »."},{"id":"notice-33","title":"Le Corvélion","sourceTitle":"","latin":"","subtitle":"Gardien des Falaises","kind":"Esprit / hybride","filter":"esprit","files":[34],"description":"Chimère majestueuse mi-lion mi-aigle, le Corvélion veille sur les falaises et n’attaque que si on le provoque.","facts":{"taille":"2 à 3 m au garrot / envergure 4-5 m","poids":"250 à 350 kg","origine":"Côtes du Royaume-Uni","habitat":"Falaises escarpées et sommets rocheux","status":"animal","classification":"4x"},"keywords":"corvélion gardien falaises chimère lion aigle","summary":"Le Corvélion est une chimère solitaire et farouche qui vit sur les falaises et les sommets rocheux. Il défend son territoire et n’attaque que lorsqu’il est provoqué."},{"id":"notice-34","title":"Le Facocendre","sourceTitle":"","latin":"Sus Pyrocineris","subtitle":"Un sanglier tout feu tout flamme","kind":"Terrestre","filter":"terrestre","files":[35],"description":"Le Facocendre est un sanglier dont le pelage s’enflamme lorsqu’il est en colère. Sa fumée et ses braises marquent son territoire.","facts":{"taille":"1,20 à 1,50 m long / 60-80 cm garrot","poids":"Jusqu’à 100 kg","origine":"Savanes d’Afrique","habitat":"Prairies, savanes boisées","status":"animal","classification":"4x"},"keywords":"facocendre sus pyrocineris sanglier feu","summary":"Le Facocendre vit dans les prairies et les savanes boisées. Colérique et territorial, il peut s’enflammer et laisser fumée et braises sur son passage."},{"id":"notice-35","title":"Les Chimères","sourceTitle":"","latin":"","subtitle":"","kind":"Esprit / hybride","filter":"esprit","files":[36,37,38],"description":"Les Chimères résultent de la fusion de plusieurs espèces, une hybridité souvent instable. On distingue trois types : naturelles, artificielles et maudites.","facts":{"origine":"Expériences alchimiques, malédictions, phénomènes naturels","status":"animal"},"keywords":"chimères hybrides fusion espèces","summary":"Les Chimères naissent de fusions naturelles, d’expériences alchimiques ou de malédictions. Leur stabilité et leur comportement varient selon leur origine; Manticore, Corvélion, Owlazar et Vaghest en sont des exemples."},{"id":"notice-36","title":"Les Gargouilles Sentinelles","sourceTitle":"","latin":"Gargulio sentinella","subtitle":"","kind":"Objet enchanté","filter":"artefact","files":[39,40],"description":"Les Gargouilles Sentinelles sont des statues de pierre conscientes fixées aux édifices anciens. Elles observent et collectent des informations pour le CMS.","facts":{"taille":"1,2 m à 3,5 m","poids":"300 kg à plus d’une tonne","habitat":"Corniches, clochers, contreforts et arches","status":"non être","classification":"3x"},"keywords":"gargouilles sentinelles gargulio sentinella cms","summary":"Immobiles mais conscientes, les Gargouilles Sentinelles surveillent corniches, clochers et arches. Elles collectent des informations pour le CMS sans quitter leur poste."},{"id":"notice-37","title":"Le Owlzawur","sourceTitle":"Le Vâghest","latin":"","subtitle":"Le témoin des magies qui dépassent leur maître","kind":"Esprit / hybride","filter":"esprit","files":[41],"description":"Le Owlzawur est une chimère marine née d’une fusion ratée. Il conserve des éclairs de conscience humaine qui déclenchent des tempêtes; ne jamais l’affronter directement.","facts":{"origine":"Expérience magique ratée","habitat":"Fjords et mers froides d’Islande","status":"être","classification":"4x"},"keywords":"vâghest vaghest chimère maudite cheval baleine","summary":"Le Owlzawur est une chimère maudite et extrêmement territoriale. Des éclairs de conscience humaine subsistent en lui et peuvent provoquer de violentes tempêtes."},{"id":"notice-38","title":"Le Owlazar","sourceTitle":"","latin":"","subtitle":"Alors que le sort ricochait, une créature allait naître de cette erreur","kind":"Esprit / hybride","filter":"esprit","files":[42,43],"description":"L’Owlazar est né d’un sort raté d’Elzéar. Il a une tête de hibou, un corps de félin, des écailles et une queue de cerf; stable et mélancolique, il possède une vision magique.","facts":{"origine":"Sort de métamorphose précipité d’Elzéar (Brocéliande)","habitat":"Forêts sombres, ruines d’érudition, lieux de magie ancienne","status":"être","classification":"3x"},"keywords":"owlazar chimère accidentelle elzéar brocéliande","summary":"L’Owlazar est une chimère artificielle accidentelle créée par un sort de métamorphose précipité d’Elzéar. Nocturne et craintif, il est stable malgré son origine et possède une vision magique."},{"id":"notice-39","title":"L'Arkenplume","sourceTitle":"","latin":"Volucris Chromus Arken","subtitle":"La mort drapée de mille couleurs","kind":"Aérien","filter":"aerien","files":[44,45],"description":"Petit oiseau au plumage qui se colore progressivement, l’Arkenplume annonce la mort lorsqu’il devient multicolore. Quiconque l’aperçoit sous cette forme meurt peu après.","facts":{"taille":"Environ 20 cm","origine":"Sud de Honshū (plaines littorales)","habitat":"Plaines littorales ensoleillées près des points d’eau","poids":"Léger","status":"animal","classification":"2x–5x"},"keywords":"arkenplume volucris chromus arken mort couleurs honshū","longText":"**CARACTÉRISTIQUES BIOLOGIQUES**\nPetit oiseau d’environ 20 cm. Plumage changeant : gris à sa naissance, il se pare peu à peu de couleurs éclatantes. Ne se nourrit que d’eau claire.\n\n**NATURE MORTELLE**\nLorsqu’il revêt ses teintes vives, il devient un présage fatal : quiconque le voit ainsi meurt peu après, et l’oiseau perd aussitôt ses couleurs.\n\n**COMPORTEMENT**\nOiseau solitaire, discret et imitateur de chants. Mélancolique à mesure que son plumage s’illumine.","publishedFacts":{"taille":"Environ 20 cm","origine":"Sud de Honshū (plaines littorales)","habitat":"Plaines littorales ensoleillées près des points d’eau"},"summary":"L’Arkenplume est un oiseau solitaire dont le cycle de coloration est lié à la mort. Lorsqu’il devient multicolore, ceux qui l’aperçoivent meurent peu après."},{"id":"notice-40","title":"Le Thésion","sourceTitle":"","latin":"Theseus Vigilantus","subtitle":"Il porte les secrets, et juge les aventuriers au travers de ses énigmes et épreuves","kind":"Esprit / hybride","filter":"esprit","files":[46],"description":"Le Thésion est un hybride majestueux qui protège le savoir interdit. Il propose des énigmes : réussir ouvre le passage, échouer condamne à l’errance.","facts":{"taille":"Environ 4 mètres de long / 8 mètres d’envergure","origine":"Anciennes terres d’Havengard","habitat":"Seuils interdits, ruines, bibliothèques oubliées, falaises","status":"être","classification":"4x"},"keywords":"thésion theseus vigilantus gardien savoir sphinx havengard","longText":"**CARACTÉRISTIQUES BIOLOGIQUES**\nÊtre hybride majestueux : corps d’un lion puissant, torse et visage d’un loup sauvage, et de vastes ailes diaphanes. Mesure près de 4 mètres de long pour 8 mètres d’envergure.\n\n**DESCRIPTION ET RÔLE**\nProtecteur du savoir interdit. Propose une énigme en guise d’épreuve : répondre juste ouvre le passage, échouer condamne à l’errance éternelle.\n\n**COMPORTEMENT**\nSolitaire et patient. Il n’attaque jamais sans raison et préfère tester la sagesse que la force. Sa mémoire est légendaire.","publishedFacts":{"taille":"4 m / 8 m d’envergure","origine":"Anciennes terres d’Havengard","habitat":"Seuils interdits, ruines, bibliothèques oubliées"},"publishedSubtitle":"Il porte les secrets, et juge les aventuriers","summary":"Gardien du savoir interdit, le Thésion est un hybride imposant doté d’ailes de brume. Il met les voyageurs à l’épreuve par des énigmes et privilégie la sagesse à la force."},{"id":"notice-41","title":"La Chimaira","sourceTitle":"La Chimaera","latin":"","subtitle":"Il est surprenant que sa description soit si précise, vu la dangerosité de la bête","kind":"Esprit / hybride","filter":"esprit","files":[47],"description":"Hybride terrifiante à tête de lion, corps de chèvre et queue de serpent ou de dragon, la Chimaira est presque invincible. Solitaire et destructrice, elle ne partage son territoire avec aucune créature.","facts":{"taille":"Imposante (grande)","origine":"Lycie (mythologie grecque) – fille de Typhon et Échidna","habitat":"Régions montagneuses et escarpées, plaines rocheuses","status":"animal","classification":"5x"},"keywords":"chimaera chimère hybride terrifiante lycie typhon","summary":"La Chimaira est une créature hybride presque invincible, solitaire et destructrice. Elle occupe les régions montagneuses et rocheuses, où aucune autre créature ne partage son territoire."},{"id":"notice-42","title":"Le Mauresut","sourceTitle":"","latin":"","subtitle":"Certains animaux miaulent, chassent ou dorment... le Mauresut, lui, veille sur vos rêves","kind":"Félin mythique","filter":"esprit","files":[48],"description":"Félin mythique à sept queues, le Mauresut est réputé veiller sur les rêves et protéger les maisons des mauvais songes.","facts":{"taille":"Non spécifiée (félin)","poids":"Non spécifié","classification":"4x","origine":"Rives du Nil (temples de Bastet)","habitat":"Lieux calmes, chauds et baignés de lumière : temples, toits de pierre, jardins silencieux et chambres royales","status":"animal"},"keywords":"mauresut félin mythique rêves Nil Bastet sept queues cauchemars","summary":"Félin mythique au pelage soyeux et aux sept queues, le Mauresut est réputé protéger les rêves. Né sur les rives du Nil et associé à Bastet, il fréquente les lieux calmes et lumineux. Discret et non hostile, il parcourt les songes la nuit, chasse les pensées sombres et peut troubler les esprits fragiles par ses illusions. Un miroir poli ou quelques gouttes de miel peuvent gagner sa bienveillance; il protège alors la maison des mauvais rêves. Il vit entre 80 et 200 ans.","longText":"Nature : félin mythique et gardien des rêves.\\n\\nNATURE ET APPARENCE\\nFélin mythique au pelage soyeux, le Mauresut se distingue par ses nuances profondes — noir d’encre, argent brumeux ou lilas lunaire. Sa silhouette semble se dissoudre dans la lumière, tandis que ses sept queues fines ondulent comme des volutes de fumée. Ses yeux bicolores, mêlant or et azur, paraissent contenir des fragments d’étoiles. Sous son apparence féline, il dissimule une aura apaisante et une puissance liée aux songes.\\n\\nORIGINE ET SYMBOLISME\\nNé sur les rives du Nil, le Mauresut fut consacré aux temples de Bastet, déesse de la paix et des rêves. Les pharaons le considéraient comme un gardien spirituel, capable de protéger leurs songes et d’inspirer la sagesse divine. Ses sept queues symbolisent les sept niveaux de l’esprit éveillé. Il est dit que son ronronnement pouvait harmoniser les rêves d’un peuple entier, dissipant les cauchemars collectifs.\\n\\nCOMPORTEMENT ET HABITAT\\nLe Mauresut préfère les lieux calmes, chauds et baignés de lumière : temples abandonnés, toits de pierre, jardins silencieux ou chambres royales. Le jour, il sommeille au soleil ; la nuit, il parcourt les songes humains, chassant les pensées sombres. Discret, il se manifeste rarement : un reflet dans l’eau, un miaulement lointain ou une empreinte dans le sable suffisent à trahir son passage. En danger, il disparaît dans un éclat doré, comme une poussière solaire se dissolvant dans l’air.\\n\\nRELATIONS ET INTERACTIONS\\nLe Mauresut n’est pas hostile, mais sa présence exige un esprit clair. Ses illusions peuvent troubler ceux dont la conscience vacille, les enfermant dans des reflets trompeurs d’eux-mêmes. Les mages du désert suspendaient autrefois des clochettes d’or près de leurs lits pour contenir son influence. Un miroir poli ou quelques gouttes de miel suffisent à gagner sa bienveillance ; il protège alors la maison du mauvais songe.\\n\\nCROYANCES ET THÉORIES\\nCertains manuscrits affirment que les Mauresuts furent les gardiens secrets des rêves royaux, veillant sur les souverains en transe spirituelle. Des fresques effacées les montrent veillant sur des dormeurs auréolés de lumière. Officiellement, ils ne seraient qu’un symbole artistique de vigilance, mais de nombreux mages prétendent qu’ils vivent encore, cachés dans les reflets du Nil ou les tombeaux de leurs anciens maîtres.\\n\\nDURÉE DE VIE\\nLe Mauresut vit entre 80 et 200 ans."},{"id":"notice-43","title":"La Manticore","sourceTitle":"","latin":"","subtitle":"Tenter quoi que ce soit contre cette monstruosité serait insensé","kind":"Esprit / hybride","filter":"esprit","files":[49],"description":"Fauve massif au visage humain et à la queue de dards venimeux, la Manticore est rusée, solitaire et territoriale. Elle symbolise la peur de l’étranger.","facts":{"taille":"2,4–3 m au garrot / 4–5 m de long total","poids":"1 à 2 tonnes","origine":"Récits persans (martya-khor)","habitat":"Terres dures et arides, cavernes profondes, ravins pierreux","status":"animal","classification":"5x"},"keywords":"manticore fauve hybride persan mangeur hommes","longText":"**CARACTÉRISTIQUES BIOLOGIQUES**\nFauve massif au pelage rouge sombre. Combine une carrure de lion et un visage étonnamment humain. Mesure 2,4–3 m au garrot et pèse jusqu’à 1–2 tonnes. Queue armée de dards venimeux capables d’être projetés à distance.\n\n**COMPORTEMENT**\nSolitaire et territoriale. Elle n’attaque pas avec aveuglement : elle guette, contourne, attend la vulnérabilité. Intelligence rusée.\n\n**MYTHE**\nSymbolise l’inhospitalité des terres lointaines et la peur de l’étranger.","publishedFacts":{"taille":"2,4–3 m au garrot / 4–5 m de long","poids":"1 à 2 tonnes","origine":"Récits persans (martya-khor)","habitat":"Terres dures et arides, cavernes profondes"},"summary":"La Manticore est un prédateur intelligent et solitaire au corps massif, au visage humain et à la queue armée de dards venimeux. Les récits persans la présentent comme un symbole de la peur de l’étranger."},{"id":"notice-44","title":"Le Sylphorix","sourceTitle":"Sylphoria","latin":"","subtitle":"Une lueur d’espoir ou un présage de renouveau, il porte l’invisible et l’inconnu","kind":"Esprit / hybride","filter":"esprit","files":[51],"description":"Immense oiseau spectral et éthéré, le Sylphorix est solitaire et paisible et n’interagit jamais directement. Sa présence annonce un changement ou un appel à la paix intérieure; ne pas le toucher.","facts":{"taille":"Environ 4 mètres de long / 8 mètres d’envergure","poids":"Nul (éthéré)","origine":"Inconnue (récits d’Aetheris)","habitat":"Hauteurs inaccessibles, cieux lointains, lieux de lumière diffuse","status":"esprits","classification":"4x"},"keywords":"sylphoria sylphorix oiseau spectral aetheris edgar malvoisin","summary":"Le Sylphorix est un esprit ancien rarement aperçu dans les hauteurs ou les lieux baignés d’une lumière diffuse. Son apparition annoncerait un changement ou inviterait à retrouver la paix intérieure; le toucher peut avoir des conséquences."},{"id":"feraluna","title":"La Féraluna","sourceTitle":"","latin":"","subtitle":"Ours spectral des nuits silencieuses","kind":"Esprit","filter":"esprit","files":[50],"description":"Petit ours au pelage pâle et lumineux, la Féraluna observe les voyageurs sans intervenir. Elle semble née du silence et de la contemplation.","facts":{"habitat":"Bois et lieux calmes","status":"esprits","classification":"4x"},"keywords":"feraluna féráluna ours spectral silence","longText":"Créature d’observation pure, la Féraluna ne chasse pas, n’interagit pas et demeure à l’écart du monde. La planche la décrit comme un petit ours spectral inspiré des Premières Nations, associé au silence, à la mémoire et à la contemplation.","summary":"La Féraluna est une présence discrète au pelage pâle et lumineux. Elle observe les voyageurs sans intervenir, et la planche l’associe au silence et à la contemplation."},{"id":"gribouillard","title":"Le Gribouillard","sourceTitle":"","latin":"Bestiola scribacula","subtitle":"","kind":"Terrestre","filter":"terrestre","files":[],"description":"Petit animal de bibliothèque, entre poussin et rongeur miniature, le Gribouillard est attiré par l’encre et adore raturer les manuscrits. Inoffensif mais envahissant, il peut même altérer les notes de sorciers. Une variété rare reproduit parfaitement les lettres et les symboles.","facts":{"taille":"Environ 20 cm (queue comprise)","poids":"Très légère","classification":"2x","origine":"Moyen-Orient","habitat":"Bibliothèques, bureaux et salles d’études mal rangés, dortoirs en désordre","status":"animal"},"keywords":["gribouillard","encre","parchemin","bibliothèque","manuscrit"],"summary":"Petit animal inoffensif, entre poussin et rongeur miniature, le Gribouillard adore l’encre et sème des ratures sur les manuscrits. Curieux et envahissant, il peut perturber les travaux des sorciers. Une variété rare reproduit lettres et symboles à la perfection.","longText":"**Apparence**\nEntre poussin et rongeur miniature, le Gribouillard est recouvert d’un duvet tacheté aux couleurs de l’encre. De petites plumes sur sa tête frémissent à chaque mouvement. Il possède des pattes avant palmées, un petit bec solide et des yeux vifs souvent tachés d’encre. Sa taille atteint environ 20 cm, queue comprise, et il est très léger.\n\n**Caractère**\nCurieux, espiègle, envahissant et non agressif.\n\n**Habitudes et nuisances**\nAttiré par l’encre, il plonge ses pattes dans les encriers puis court sur les parchemins. Il aime mâchouiller, raturer et griffonner tout ce qui ressemble à du papier : parchemins, livres de bibliothèque, lettres et carnets. Certains sorciers affirment même que des sorts mal formulés provenaient de ses gribouillages sur leurs notes. Il ne représente aucun danger réel, mais peut être particulièrement agaçant.\n\n**Alimentation**\nEncre séchée, petits insectes et poussière de bibliothèque.\n\n**Origine et habitat**\nOriginaire du Moyen-Orient, il fréquente les bibliothèques, les bureaux et salles d’études mal rangés ainsi que les dortoirs en désordre.\n\n**Limiter sa présence**\nDes encres répulsives parfumées aux herbes métalliques, comme la verdoise d’écarlate, peuvent aider à limiter son invasion. On peut aussi placer un pot de dictame sur le bureau ou laisser en appât de vieux rouleaux imbibés d’encre. Imprévisible, il peut être élevé comme compagnon de bibliothèque… avec presque toujours des regrets.\n\n**Variété rare**\nUne variété capable de reproduire parfaitement lettres et symboles divise les chercheurs.\n\n**Durée de vie**\nDe 120 à 200 ans."}];

const POTIONS = [{"id":"nanice-jouvencine","name":"Nanice de Jouvencine","type":"Potion curative","description":"La Nanice de Jouvencine est une potion destinée aux soins mineurs. Elle permet de traiter les petites blessures, mais ne peut en aucun cas faire repousser un membre. Son efficacité est comparable au sortilège Tbobo.","usage":"Elle peut être appliquée directement sur une plaie ou être consommée par voie orale.","appearance":"Liquide vert légèrement épais, parcouru de filaments verts et blancs qui ne se mélangent jamais. Sa consistance rappelle celle d’un sirop.","taste":"Mélange subtil de jus de pomme et de jus de framboise.","ingredients":["Eau de tristesse.","Baie de Mandragore : apporte les propriétés curatives.","Fleur de Silmera."],"preparation":["Chauffer à feu doux.","Ajouter l’eau de tristesse.","Tourner 5 fois dans le sens horaire.","Ajouter une baie de Mandragore.","Tourner 3 fois dans le sens antihoraire.","Ajouter une fleur de Silmera.","Tourner 3 fois dans le sens antihoraire.","Passer à feu fort."],"incantation":"Elixirem Sanationis","finishing":"Valider chaque étape de préparation, puis remplir la fiole.","variant":{"name":"Nanice de Jouvencine Maxima","description":"Version supérieure de la potion, reconnaissable à ses deux petites étoiles sur la fiole. Elle possède une appellation spécifique la distinguant de la préparation classique."},"aroma":"Printanière"},{"id":"humecumes","name":"Nanis d’Humécume","type":"Potion d’altération de capacité","description":"La potion d’Humécumes permet de respirer et de parler librement sous l’eau. Une seule gorgée modifie temporairement les poumons afin qu’ils absorbent l’oxygène présent dans l’eau. L’effet dure plusieurs minutes et varie selon la constitution de l’utilisateur.","origin":"Les premières traces remontent aux communautés côtières d’Écosse, où des sorciers pêcheurs cherchaient à prolonger leurs capacités d’apnée.","usage":"Une seule gorgée suffit à déclencher temporairement l’effet. La potion est particulièrement appréciée des explorateurs aquatiques.","appearance":"Liquide limpide contenant des cristaux en forme de petits coraux multicolores. Le bleu et le vert dominent, parfois accompagnés de violet, de brun et de rouge. Plus la Melorine est fraîche, plus les coraux sont nombreux et variés.","texture":"Légèrement gélatineuse. Les cristaux doivent être mâchés individuellement ; leur texture granuleuse rend la dégustation désagréable.","taste":"Fortement salé et iodé, rappelant l’air marin et l’eau d’une marée montante.","aroma":"Évoque une marée matinale : fraîche et légèrement piquante, comme l’air vif des côtes.","ingredients":["Racine d’Herbecorce — récoltée sur l’île du Pêcheur.","Melorine — algue poussant uniquement dans les eaux stagnantes et peu profondes.","Eau de tristesse — base de la préparation, bien moins pure que l’eau de pureté."],"preparation":[{"text":"Chaudron à feu fort","duration":5},{"text":"Ajouter 1 dose d’eau de tristesse","duration":5},{"text":"Mélanger 5 fois dans le sens antihoraire","duration":9},{"text":"Ajouter 1 racine d’Herbecorce","duration":5},{"text":"Mélanger 3 fois dans le sens horaire","duration":6},{"text":"Chaudron à feu faible","duration":5},{"text":"Ajouter 1 Melorine","duration":5},{"text":"Mélanger 5 fois dans le sens antihoraire","duration":9},{"text":"Chaudron à feu fort","duration":5}],"incantation":"Afflatus Maritis","sideEffects":["Hors de l’eau, la potion peut provoquer l’expulsion de bulles ou une envie irrépressible de plonger. La sensation de manque d’oxygène peut devenir dangereuse.","Une consommation excessive peut rendre la voix rauque ou provoquer une perte temporaire de la voix. L’utiliser pour accélérer volontairement la voix, notamment chez les adolescents, est fortement déconseillé."],"conservation":"Les cristaux coralliens doivent impérativement rester immergés dans leur solution visqueuse. À l’air libre, ils perdent leurs propriétés et finissent par se dissoudre en dégageant une odeur marécageuse.","particularity":"Malgré son goût peu apprécié, cette potion est recherchée pour ses propriétés pratiques et récréatives. Elle aide à explorer les profondeurs sans contrainte."},{"id":"nanis-esprit-clair","name":"Nanis d’esprit clair","type":"Potion curative","subcategory":"Potion de dissipation","function":"Restaure la lucidité et neutralise les troubles de l’esprit d’origine magique.","description":"Cette potion dissipe les effets magiques qui altèrent les facultés mentales. Elle peut notamment neutraliser un sort de confusion et aider la personne à retrouver ses esprits.","limitations":"Ce n’est pas un remède universel : elle ne soigne ni les blessures physiques, ni la fatigue, ni les troubles d’origine non magique. Elle ne permet pas non plus de retrouver des objets perdus ou des souvenirs oubliés.","dosage":"Une seule gorgée suffit généralement pour obtenir l’effet recherché.","appearance":"Liquide limpide semblable à de l’eau de rivière. De petites étincelles lumineuses scintillent au fond de la fiole et, lorsqu’on l’agite, dansent dans le liquide en produisant une légère lueur bleu électrique.","color":"Transparente avec des reflets bleu électrique.","texture":"Fluide et limpide.","aroma":"Inodore.","taste":"Neutre.","temperature":"Sensation de fraîcheur.","contact":"Provoque un léger picotement sur les doigts. Les premières gorgées peuvent surprendre par leur fraîcheur et ce picotement.","ingredients":["1 dose d’Eau de tristesse.","1 Fleur de Silmera.","1 Rosimence."],"preparation":[{"text":"Chauffer à feu moyen","duration":5},{"text":"Ajouter 1 dose d’Eau de tristesse","duration":5},{"text":"Mélanger 2 fois dans le sens horaire","duration":6},{"text":"Ajouter 1 Fleur de Silmera","duration":5},{"text":"Mélanger 3 fois dans le sens horaire","duration":6},{"text":"Ajouter 1 Rosimence","duration":5},{"text":"Mélanger 5 fois dans le sens horaire","duration":9},{"text":"Passer à feu doux","duration":5}],"incantation":"Mens Clara","incantationDuration":15,"totalTime":"61 secondes","sideEffects":["Insomnie : peut perturber le sommeil.","Brain freeze : sa fraîcheur intense peut provoquer de violents maux de tête.","Dépendance : une addiction peut apparaître au-delà de 5 fioles consommées sur une période de 3 jours."],"testimony":"Timor Plume aurait déclaré avoir bu cette potion pour clarifier ses idées. Résultat : ses idées étaient effectivement plus claires, mais il avait quand même oublié ses chaussettes."},{"id":"souffle-aelyne","name":"Le Souffle d’Aelyne","description":"La planche décrit une préparation à feu faible, composée d’eaux de pureté, de dents d’Ophidrel et de rosimences. Après plusieurs mélanges dans les deux sens, le feu est éteint avant de réciter « malum iocum ». L’effet de la potion n’est pas précisé.","ingredients":["4 eaux de pureté","2 dents d’Ophidrel","10 rosimences"],"preparation":["Feu faible.","Ajouter 4 eaux de pureté.","Tourner 10 fois dans le sens horaire.","Ajouter 2 dents d’Ophidrel.","Tourner 8 fois dans le sens antihoraire.","Ajouter 10 rosimences.","Tourner 3 fois dans le sens antihoraire.","Éteindre le feu."],"incantation":"malum iocum","plate":"public/images/potions/le-souffle-daelyne.png"},{"id":"chauvus-maximus","name":"Chauvus Maximus","description":"La recette associe des baies de Mandragore, des fleurs de Silmera et de la poudre de Cornelongue. Elle alterne les mélanges horaires et antihoraires, avec un palier sur feu moyen puis un passage bref à feu fort, avant l’incantation « Amissio capillorum ». La planche ne précise pas l’effet de la potion.","ingredients":["5 baies de Mandragore","2 fleurs de Silmera","2 poudres de Cornelongue"],"preparation":["Placer 5 baies de Mandragore dans le creuset.","Maintenir sur feu moyen pendant 10 secondes.","Agiter dans le sens horaire pendant 1 tour.","Agiter ensuite 2 tours dans le sens antihoraire.","Ajouter 2 fleurs de Silmera.","Agiter 3 tours horaires.","Incorporer 2 poudres de Cornelongue.","Agiter 4 tours antihoraires.","Augmenter à feu fort pendant 5 secondes."],"incantation":"Amissio capillorum","plate":"public/images/potions/chauvus-maximus.png"},{"id":"calvas-finitas","name":"Calvas Finitas","type":"Potion de repousse capillaire","subcategory":"Potion capillaire","function":"Favorise la repousse des cheveux et des poils après une calvitie magique.","description":"La Calvas Finitas fait repousser les cheveux et les poils perdus. Recréée à partir de la formule oubliée du Chauvus Maximus, elle associe les propriétés des baies de Mandragore, de la fleur de Silméra et de la Barnélite. Une goutte suffit selon le récit, mais une dose excessive peut entraîner une repousse spectaculaire et incontrôlée.","origin":"La formule fut reconstituée quelques années après la création du Chauvus Maximus, dont la recette avait été perdue. Maître Elben Tifol redécouvrit la Calvas Finitas lors d’une épidémie de calvitie magique.","source":"Calvas Finitas — Anna Morticia","usage":"Une goutte suffit à faire repousser la pilosité. À boire avec prudence.","texture":"Sèche et sablonneuse, avec de longues fibres qui peuvent rester coincées dans la gorge.","aroma":"Identique à l’odeur du sable chaud.","taste":"Aucun goût. La texture est si atroce qu’aucun goût ne l’accompagne.","ingredients":["Baies de Mandragore — 5 à l’étape 2 et 5 à l’étape 4 (10 au total). Leurs vertus curatives favorisent une repousse sans douleur post-repousse.","Fleur de Silméra — 1. Aide à contrer les effets secondaires et rend éclat et brillance aux cheveux nouvellement formés ainsi qu’à la peau du crâne.","Barnélite — 1. Aide à récupérer les cheveux et les poils perdus; ses propriétés curatives neutralisent celles des baies de Mandragore."],"preparation":[{"text":"Passer le chaudron à feu fort.","duration":5},{"text":"Ajouter 5 baies de Mandragore.","duration":10},{"text":"Mélanger en tournant 2 fois dans le sens horaire.","duration":6},{"text":"Ajouter 5 baies de Mandragore.","duration":10},{"text":"Mélanger en tournant 5 fois dans le sens antihoraire.","duration":9},{"text":"Passer le chaudron à feu moyen.","duration":5},{"text":"Ajouter 1 fleur de Silméra.","duration":5},{"text":"Ajouter 1 Barnélite.","duration":5},{"text":"Mélanger en tournant 2 fois dans le sens horaire.","duration":6},{"text":"Mélanger en tournant 2 fois dans le sens antihoraire.","duration":6},{"text":"Prononcer l’incantation.","duration":15}],"incantation":"folliculi renascentur","incantationDuration":15,"totalTime":"82 secondes","limitations":"Une dose excessive peut provoquer une repousse torrentielle et incontrôlée. Ne pas la boire à la légère.","sideEffects":["Une dose excessive peut faire pousser une chevelure abondante en mèches folles.","Des témoins rapportent des sourcils, des moustaches ou une pilosité d’une longueur démesurée."],"history":"La Calvas Finitas apparut quelques années après le Chauvus Maximus, célèbre pour faire pousser les cheveux des créatures les plus chauves. La formule originale se perdit après le premier cercle d’alchimistes. Lorsqu’une épidémie de calvitie magique toucha sorciers, apprentis et familles entières, les perruques enchantées ne suffirent plus. Un mage déterminé fouilla bibliothèques, cavernes et greniers poussiéreux, affronta ses maux de crâne et finit par recréer la potion.\n\nLa première diffusion publique eut lieu au Banquet des Mille Mèches, organisé en 1869 par le Conseil des Arcanistes pour célébrer Maître Elben Tifol. L’Archimage Gregorius retrouva une chevelure argentée et un ambassadeur britannique ses moustaches torsadées. La Grande Sorcière Rhémanda des Trois Aspects tripla la dose : une cascade de cheveux dorés jaillit de son crâne et s’étendit sur près de quatre mètres. Selon les témoins, les mèches serpentaient autour des convives et trois acolytes durent les dompter avec un peigne improvisé. Maître Tifol déclara : « La potion est parfaite. C’est l’audace de certains crânes qui dépasse mes espérances. » Depuis, le banquet rappelle qu’une potion miraculeuse n’est pas à prendre à la légère.","plates":["public/images/potions/calvas-finitas/01-couverture.png","public/images/potions/calvas-finitas/02-caracteristiques.png","public/images/potions/calvas-finitas/03-origine.png","public/images/potions/calvas-finitas/04-reconstitution.png","public/images/potions/calvas-finitas/05-ingredients.png","public/images/potions/calvas-finitas/06-preparation.png","public/images/potions/calvas-finitas/07-banquet.png","public/images/potions/calvas-finitas/08-banquet-suite.png","public/images/potions/calvas-finitas/09-banquet-conclusion.png"]},{"id":"potion-humecume","name":"Potion d’Humécume","type":"Potion d’altération de capacité","description":"La potion d’Humécumes permet de respirer et de parler librement sous l’eau. Une seule gorgée modifie temporairement les poumons afin qu’ils absorbent l’oxygène présent dans l’eau. L’effet dure plusieurs minutes et varie selon la constitution de l’utilisateur.","origin":"Les premières traces remontent aux communautés côtières d’Écosse, où des sorciers pêcheurs cherchaient à prolonger leurs capacités d’apnée.","usage":"Une seule gorgée suffit à déclencher temporairement l’effet. La potion est particulièrement appréciée des explorateurs aquatiques.","appearance":"Liquide limpide contenant des cristaux en forme de petits coraux multicolores. Le bleu et le vert dominent, parfois accompagnés de violet, de brun et de rouge. Plus la Melorine est fraîche, plus les coraux sont nombreux et variés.","texture":"Légèrement gélatineuse. Les cristaux doivent être mâchés individuellement ; leur texture granuleuse rend la dégustation désagréable.","taste":"Fortement salé et iodé, rappelant l’air marin et l’eau d’une marée montante.","aroma":"Évoque une marée matinale : fraîche et légèrement piquante, comme l’air vif des côtes.","ingredients":["Eau de pureté — 10 doses.","Racine d’Herbecorce — 1, récoltée sur l’île du Pêcheur.","Melorine — 1, algue poussant uniquement dans les eaux stagnantes et peu profondes."],"preparation":[{"text":"Chaudron à feu fort","duration":5},{"text":"Ajouter 10 doses d’eau de pureté","duration":5},{"text":"Mélanger 5 fois dans le sens antihoraire","duration":9},{"text":"Ajouter 1 racine d’Herbecorce","duration":5},{"text":"Mélanger 3 fois dans le sens horaire","duration":6},{"text":"Chaudron à feu faible","duration":5},{"text":"Ajouter 1 Melorine","duration":5},{"text":"Mélanger 5 fois dans le sens antihoraire","duration":9},{"text":"Chaudron à feu fort","duration":5}],"incantation":"Afflatus Maritis","sideEffects":["Hors de l’eau, la potion peut provoquer l’expulsion de bulles ou une envie irrépressible de plonger. La sensation de manque d’oxygène peut devenir dangereuse.","Une consommation excessive peut rendre la voix rauque ou provoquer une perte temporaire de la voix. L’utiliser pour accélérer volontairement la voix, notamment chez les adolescents, est fortement déconseillé."],"conservation":"Les cristaux coralliens doivent impérativement rester immergés dans leur solution visqueuse. À l’air libre, ils perdent leurs propriétés et finissent par se dissoudre en dégageant une odeur marécageuse.","particularity":"Malgré son goût peu apprécié, cette potion est recherchée pour ses propriétés pratiques et récréatives. Elle aide à explorer les profondeurs sans contrainte."},{"id":"potion-kiri","name":"Potion Kiri","type":"Potion hilarante","subcategory":"Potion qui fait rire","function":"Provoque le rire.","description":"Potion destinée à déclencher le rire.","source":"Monsieur Richmond","ingredients":["Eau de tristesse — 1.","Rosimence — 1.","Gaz de pince — 1.","Sève bavarde — 1."],"preparation":[{"text":"Passer le chaudron à feu faible."},{"text":"Ajouter 1 eau de tristesse."},{"text":"Ajouter 1 Rosimence."},{"text":"Tourner 4 fois dans le sens horaire."},{"text":"Ajouter 1 gaz de pince."},{"text":"Tourner 2 fois dans le sens antihoraire."},{"text":"Ajouter 1 sève bavarde."},{"text":"Tourner 2 fois dans le sens antihoraire."},{"text":"Prononcer l’incantation."}],"incantation":"Risus impetus"},{"id":"potion-memorial","name":"Potion mémorial","type":"Type non précisé","description":"L’effet de la Potion mémorial n’est pas précisé dans les notes. La recette indique une préparation avec de la sève, de l’eau de tristesse, des pierres de lune et des fleurs de crâne, achevée par l’incantation « Memorial Succensa ».","ingredients":["Sève — quantité : 3 (unité non précisée).","Eau de tristesse — quantité : 2 (unité non précisée).","Pierre de lune — 2.","Fleur de crâne — 4."],"preparation":["Passer le chaudron à feu moyen.","Ajouter de la sève (quantité indiquée : 3).","Ajouter de l’eau de tristesse (quantité indiquée : 2).","Ajouter 2 pierres de lune.","Prononcer l’incantation « Memorial Succensa ».","Tourner 6 fois dans le sens horaire.","Passer le chaudron à feu faible.","Ajouter 4 fleurs de crâne.","Tourner 6 fois dans le sens antihoraire.","Passer le chaudron à feu moyen.","Prononcer l’incantation « Memorial Succensa »."],"incantation":"Memorial Succensa"}];

const SUBJECT_NOTES = {"sortileges":[{"id":"defendo","title":"Defendo","type":"Sort défensif","summary":"Defendo crée une barrière qui protège son lanceur contre les objets et attaques physiques, mais laisse passer les attaques magiques. Aucun contresort n’est connu. La fiche présente aussi plusieurs variantes, dont Defendo Maxima, très énergivore, et Defendo Initas, réservé aux Oracles de Feu.","content":"Type : Sort défensif\n\nOrigines :\nLe sort Defendo tire son origine du terme Defendréré, datant du XVe siècle. Il s'agit d'un sort de protection conçu pour bloquer les attaques physiques et protéger son lanceur.\n\nEffet :\nDefendo génère une barrière défensive capable de bloquer les objets et attaques de nature physique. Il est cependant inefficace contre les attaques magiques. Le sort ne possède aucun contresort connu.\n\nVariantes :\nDefendo de Faction : Variante adaptée aux traditions et aux techniques propres à chaque faction.\nDefendo Fidelis : Variante spécialisée dont les propriétés sont liées à la fidélité.\nDefendo Téraé : Variante associée aux forces terrestres.\nDefendo de Selki : Variante propre aux Selkis.\nDefendo de Vampire et Lycan : Variantes adaptées aux particularités de ces espèces.\nDefendo Maxima : Version particulièrement puissante. Sa barrière argentée vibre à chaque impact. Très énergivore, elle nécessite une grande quantité d'énergie magique.\nDefendo Initas : Version offrant une protection plus durable dans le temps. Des flammes parcourent le corps du lanceur durant son activation. Cette variante est exclusivement réservée aux Oracles de Feu.\n\nLimites :\nDefendo ne bloque que les attaques et objets physiques. Les sorts et autres manifestations magiques peuvent traverser sa protection. Les variantes les plus puissantes nécessitent une maîtrise et une réserve d'énergie considérables.\n\nParticularité :\nDefendo ne possède aucun contresort connu, ce qui en fait un sort défensif particulièrement fiable contre les agressions physiques.","details":[]},{"id":"desarmo","title":"Désarmo","type":"Sort d’entrave","summary":"Désarmo arrache à un adversaire l’arme ou l’objet qu’il tient, sans provoquer de blessure directe. Rapide, silencieux et de faible intensité, il est présenté comme utile en duel rapproché. La fiche retrace son origine espagnole au VIe siècle et son perfectionnement par Lucia et Anna Gambeta.","content":"Type : Sort d'entrave\n\nDescription :\nDésarmo est un sort destiné à priver un adversaire de son arme principale ou de tout objet qu'il tient en main. Il projette une force invisible qui arrache violemment l'objet à son porteur.\n\nEffet :\nPortée : Courte à moyenne.\nDurée : Instantanée.\nIntensité : Faible.\nConcentration : Faible, permettant un lancement rapide.\nManifestation : Aucune lueur visible. Le sort produit un bref souffle d'air accompagné d'un bruit sec et rapide.\nDégâts : Aucun risque de brûlure ou de choc direct.\n\nUtilisation :\nParticulièrement efficace lors des duels rapprochés, Désarmo permet de neutraliser rapidement un adversaire sans lui infliger de blessures. Il constitue un sort défensif accessible, notamment pour les sorciers débutants.\n\nLimites et risques :\nSa faible intensité constitue sa principale limite. Le sort devient inefficace si l'adversaire ne tient aucun objet susceptible d'être arraché. Il ne présente aucun effet secondaire connu.\n\nRéglementation :\nAucune interdiction particulière. Désarmo est considéré comme un pilier de la magie réglementaire, privilégiant la neutralisation plutôt que la violence.\n\nOrigines :\nOriginaire d'Espagne au VIe siècle, le sort fut perfectionné par Lucia et Anna Gambeta, deux figures emblématiques des combats clandestins. Leur maîtrise du sort contribua à populariser son utilisation et donna naissance à la célèbre loi Gambeta, fondée sur un principe simple : neutraliser sans tuer.","details":[]},{"id":"tibobo","title":"Tibobo","type":"Sortilège curatif","summary":"Tibobo est un sort simple de soin des blessures superficielles, créé par l’apprenti Tibo Bolieu pour traiter ses petits accidents. Son effet est immédiat et de très courte portée. Il ne soigne ni les blessures graves, ni les maladies, poisons ou malédictions, et ne remplace pas des soins avancés.","content":"Type : Sortilège curatif\n\nOrigines :\nL'incantation Tibobo tire son origine de son créateur, Tibo Bolieu. Le mot possède une consonance simple, douce et rassurante, à l'image de la nature plaisante et accessible du sort.\n\nTibo était un apprenti particulièrement maladroit, accumulant régulièrement égratignures et brûlures. Refusant de déranger les guérisseurs à chaque petit incident, il entreprit de créer un sort simple et sans danger pour soigner ses blessures superficielles.\n\nSans grande ambition, il cherchait simplement à se soigner lui-même. Il mit finalement au point une incantation minimale, capable d'effacer un léger saignement, un bleu ou une petite blessure.\n\nLe nom Tibobo serait né d'une contraction moqueuse de son prénom et de l'expression « petit bobo », utilisée par ses camarades.\n\nPopularité et transmission :\nLe sort se transmit rapidement, sans nécessiter de maître ni de théorie particulière. Il répondait à un besoin humain fondamental : pouvoir soigner facilement les petits accidents du quotidien.\n\nAu fil des siècles, Tibobo devint si courant que son origine fut progressivement oubliée. Il fut finalement intégré aux premiers programmes d'enseignement de la magie curative pour sa simplicité exemplaire.\n\nCaractéristiques :\nIntensité : Faible.\nPortée : Très courte, à quelques centimètres de la blessure.\nApplication : Directement sur la zone concernée.\nDurée : Effet instantané.\n\nLe sort agit uniquement sur les tissus superficiels. Il est destiné aux petites blessures et ne permet pas de traiter les lésions importantes.\n\nAspect visuel et sonore :\nUn court jet lumineux s'échappe de la baguette du lanceur. À l'impact, une flamme bleue apparaît à la surface de la peau. Elle dégage une chaleur très légère, généralement ressentie comme une sensation d'apaisement.\n\nLimites et risques :\nUne utilisation excessive de Tibobo peut avoir des effets néfastes. Le sort reste inefficace contre les blessures graves, les maladies, les poisons et les malédictions.\n\nMalgré sa simplicité, Tibobo ne doit pas être considéré comme un substitut aux soins curatifs avancés.\n\nParticularité :\nTibobo est devenu l'un des premiers réflexes magiques appris par les jeunes sorciers. Un sort né de la maladresse d'un apprenti, devenu au fil du temps un incontournable de la magie curative.","details":[]},{"id":"flamette","title":"Flamette","type":"Sortilège d’invocation","summary":"Flamette invoque une lumière douce et stable au bout de la baguette, conçue pour éclairer et réconforter sans brûler ni attaquer. La légende l’associe à Éléonore de Burmeval. Ce sort de débutant éclaire les environs proches, mais ne perce pas les ténèbres profondes ; sa lumière peut attirer des insectes.","content":"Origine et signification\nLe nom Flamette trouve son origine dans le vieux français. Il vient du mot « flamme », auquel on ajoute le diminutif « -ette ». Cette terminaison exprime une idée de douceur et de légèreté.\n\nL'incantation évoque moins la puissance destructrice du feu que sa chaleur bienveillante. Sa sonorité est douce, claire et rassurante, semblable à un murmure qui éclaire l'obscurité sans la troubler.\n\nContrairement aux formules des sorts offensifs, elle se prononce avec calme et bienveillance.\n\nHistoire et création du sortilège\nOn raconte que Flamette ne naquit ni d'une reine ni d'un duel, mais dans le silence glacé d'une nuit d'hiver.\n\nUne jeune enchanteresse du nom d'Éléonore de Burmeval s'était égarée dans une forêt enneigée. La lune était voilée et elle était incapable d'allumer un feu. Trop faible, trop tremblante et trop seule, elle ne chercha pas à invoquer la puissance, mais la douceur.\n\nElle murmura presque une prière, un appel à la lumière qui dort derrière la nuit.\n\nCe qui jaillit fut une petite flamme claire, minuscule, mais bien vivante et très fragile.\n\nCette flamme ne vacillait pas. Elle éclairait juste assez pour chasser l'angoisse et repousser la solitude.\n\nÉléonore comprit alors qu'il ne s'agissait pas d'une flamme ordinaire, mais d'une lumière de réconfort. Elle nomma ce sortilège Flamette.\n\nElle décida ensuite de le transmettre aux jeunes enfants d'un hameau qu'elle protégeait.\n\nLe sort se propagea de bouche à oreille. Les bardes l'adoptèrent pour éclairer leurs récits sous les étoiles, tandis que les guérisseurs s'en servaient pour disposer d'une lumière lorsqu'ils soignaient leurs blessés.\n\nCette histoire rappelle que la magie peut aussi être un refuge et que, dans la nuit la plus profonde, il suffit parfois d'une lueur minuscule pour rappeler que l'espérance n'est jamais éteinte.\n\nCe n'est pas un sort de puissance, mais un sort de présence.\n\nClassification et caractéristiques\nCatégorie : Invocation.\nNature : Lueur douce, stable et non agressive.\nFonction : Éclairer le lanceur et son environnement proche.\nComportement : Lumière persistante qui accompagne son utilisateur sans brûler.\nUtilisation : Éclairage et réconfort.\nDangerosité : Aucune vocation offensive.\n\nNiveau et difficulté\nNiveau : Débutant.\nMaîtrise requise : Minimale.\nCanalisation magique : Faible.\nConcentration : Faible.\nContresort : Non déterminé.\n\nAspect visuel et manifestation\nFlamette produit une lumière pure et concentrée, fixée à l'extrémité de la baguette.\n\nElle se comporte comme une torche mouvante, diffusant une lumière nette et directionnelle qui accompagne les déplacements du lanceur.\n\nLumière claire et stable.\nFixée au bout de la baguette.\nÉclairage directionnel.\nAucun son lors de l'incantation ou de la manifestation.\n\nLimites et risques\nFlamette reste un sortilège modeste.\n\nIl ne peut pas percer les ténèbres profondes, notamment celles que l'on retrouve dans la Forêt des Brumes. Il permet uniquement d'éclairer les environs proches du lanceur, sans repousser les ombres profondes.\n\nAucun effet secondaire particulier n'a été recensé, à l'exception de quelques insectes attirés par la lumière.\n\nVariantes envisagées\nFlamette Noctua\nFlamette Castor\nFlamette Phoenix\nFlamette Serpents","details":[]},{"id":"flippalto","title":"Flippalto","type":"Sortilège d’entrave","summary":"Flippalto provoque chez sa cible un salto arrière involontaire, surtout pour surprendre ou divertir sans la blesser directement. Créé par l’acrobate-sorcier Pipo il Saltatore à Versailles, il est accessible aux débutants. Il n’agit pas sur les quadrupèdes ni les cibles en lévitation ou en vol, et Defendo peut le bloquer.","content":"Origine et signification\nLe nom Flippalto est une contraction fantaisiste mêlant le terme anglais « Flip » (bascule) et l'italien « Alto » (haut). Il évoque un mouvement de bascule spectaculaire et comique.\n\nHistoire et création du sortilège\nLe sortilège vit le jour au palais de Versailles, sous le règne du Roi-Soleil. Il fut inventé par Pipo il Saltatore, un acrobate italien officiellement engagé comme amuseur de cour, mais officieusement sorcier talentueux dans l'art de la magie spectaculaire.\n\nPipo cherchait à créer un sort capable de provoquer l'illusion d'une prouesse physique, sans jamais mettre en danger sa cible.\n\nLe résultat fut un sortilège provoquant une chute élégante, semblable à un salto arrière parfaitement exécuté.\n\nIl commença par l'utiliser sur lui-même, enchaînant des voltiges impossibles et atterrissant avec une grâce presque insolente. Il devint célèbre lorsque son sort fut intégré aux comédies de balais. Il le lançait discrètement sur un partenaire, qui se retrouvait soudainement basculé, jambes vers le plafond, mais dignité toujours au sol.\n\nLe sort se répandit dans les coulisses, puis dans les académies de magie. Il devint l'un des premiers sortilèges inoffensifs dont le seul objectif était de provoquer le rire et la surprise.\n\n« Le vrai pouvoir n'est pas de blesser, mais de faire chuter quelqu'un sans qu'il ne sache pourquoi. »\n>\n— Pipo il Saltatore\n\nClassification et caractéristiques\nCatégorie : Entrave.\nNature : Sortilège de bascule et de déstabilisation.\nFonction : Provoque un mouvement de bascule comique, entraînant un salto arrière involontaire.\nUtilisation : Divertissement, surprise et déstabilisation.\nParticularité : Peut offrir un avantage tactique lors d'un duel.\n\nNiveau et difficulté\nNiveau : Débutant.\nMaîtrise requise : Minimale.\nCanalisation magique : Faible.\nConcentration : Faible.\nIntensité : Faible.\nPortée : Courte à moyenne distance.\nVitesse d'incantation : Quasi instantanée.\nContresort : Un sort simple comme Defendo peut bloquer Flippalto.\n\nAspect visuel et manifestation\nLors de l'incantation, la baguette produit une courte flamme jaune à son extrémité, suivie d'un impact lumineux au moment où le sort atteint sa cible.\n\nEffet visuel : Brève flamme jaune suivie d'un impact lumineux.\nSon : Bref et net, sans réverbération particulière.\n\nLimites et restrictions\nFlippalto présente plusieurs limites :\n\nSans effet sur les quadrupèdes.\nSans effet sur les cibles en lévitation ou en plein vol.\nSon efficacité dépend de la stabilité physique de la cible.\nAucun danger particulier recensé.\n\nStatut réglementaire : Aucune interdiction officielle. Son utilisation reste néanmoins susceptible de provoquer quelques humiliations mémorables.","details":[]},{"id":"secatrix","title":"Secatrix","type":"Sort offensif","summary":"Secatrix fait apparaître un instant une lame invisible et précise qui tranche sa cible avant de disparaître. Créé par les Minotaures pour ouvrir un passage et fuir, le sort a ensuite été repris par les sorciers humains, qui en ont effacé l’origine.","content":"Secatrix est un sort offensif dont le nom provient d'une langue très ancienne, surnommée la langue de la Pierre. Dans cette langue, Sécaré signifie « celle qui coupe » ou « celle qui tranche ».\n\nOrigine et histoire\nSecatrix est né il y a très longtemps, à une époque où un roi commit une terrible erreur. Des créatures furent alors transformées en monstres aux yeux des hommes : les Minotaures.\n\nPrivés de leurs droits, rejetés par les humains et traqués sans qu'aucune loi ne puisse les protéger, les Minotaures durent apprendre à fuir pour survivre.\n\nC'est dans cette nécessité qu'ils développèrent un sort permettant d'ouvrir un passage. Leur intention première n'était pas de tuer, mais de s'échapper : couper une corde, trancher une lance ou fendre un vêtement qui les retenait prisonniers.\n\nAinsi naquit Secatrix.\n\nUn sort court et précis, conçu non pour détruire, mais pour libérer un passage.\n\nLes sorciers humains finirent par découvrir ce sort et en subirent eux-mêmes les effets, recevant ses blessures comme celles d'une véritable lame. Ils l'étudièrent, l'imitèrent et finirent par se l'approprier. Pendant longtemps, ils prétendirent même en être les inventeurs, effaçant peu à peu son véritable héritage.\n\nClassification\nCatégorie : Sort offensif\nNature : Tranchant\nOrigine : Minotaure\nLangue d'origine : Langue de la Pierre\n\nApparence et fonctionnement\nLorsqu'il est lancé, Secatrix fait apparaître une lame invisible, extrêmement fine et précise, aussi nette qu'un éclat de verre.\n\nLa lame ne dure qu'un instant : elle apparaît, tranche sa cible, puis disparaît aussitôt.\n\nSon effet, lui, est bien réel. Tout ce qu'elle touche reste coupé. Le sort ne laisse aucune lame derrière lui, uniquement une entaille nette et précise.","details":[]}],"histoire":[{"id":"fondation-havengard","title":"L’histoire de la fondation d’Havengard","type":"Fondation","summary":"Quatre fondateurs transforment la vallée en refuge et en école : Ginsei apporte le bois et les jardins, Aldaric la sécurité, Nivara l’enseignement et la confiance, et Freya l’astronomie et la mémoire des savoirs. Leur union donne au château sa chaleur, sa protection et son ouverture au monde.","content":"À une époque où les jeunes étaient devenus des proies, menacés aussi bien par les créatures que par les Golmus, quatre fondateurs décidèrent de bâtir un refuge : le château d'Havengard.\n\nMais un simple château de pierre ne suffisait pas. Il fallait construire un lieu capable de protéger, d'accueillir et de faire grandir ceux qui y trouveraient refuge. Une architecture vivante, maintenue par la magie et la volonté de ses quatre fondateurs. Chacun insuffla au château une fonction vitale.\n\nGinsei Rongebois Tamanegui — Les Rongebois\nD'origine japonaise, Ginsei considère le bois comme une mémoire. Il façonne la charpente, les poutres apparentes, les grandes tables et les banquettes. Sous son influence, l'intérieur du château prend vie et devient chaleureux et habitable. Il s'occupe également des serres et des jardins.\n\nSans lui, Havengard ne serait qu'un immense volume de pierre. Ginsei lui apporte son ossature, sa chaleur et son intimité.\n\nAldaric Temelfort Lonbrasier — Les Lonbrasier\nPour Aldaric, construire n'est pas une simple question de technique, mais une attention prolongée portée à ceux qui franchiront les portes. Il imagine ce que ressentira un jeune fatigué, effrayé ou solitaire.\n\nIl travaille sur la sécurité architecturale : l'épaisseur des murs, les sols, la hauteur des plafonds et l'organisation des couloirs. Il ne recherche pas la beauté, mais le réconfort. Son principe est simple : envelopper sans enfermer, protéger sans isoler.\n\nNivara Vervenin — Les Vervenin\nNivara recherche la perfection, mais une perfection toujours ancrée dans l'humain. Elle imagine l'infrastructure pédagogique, réunit les professeurs et fonde une école où chacun peut poser ses questions sans jugement, progresser sans être comparé aux autres.\n\nElle construit l'institution au cœur du château. Havengard devient ainsi une école qui protège par le savoir, mais surtout par la relation de confiance entre professeurs et élèves.\n\nFreya Sveid Briselune — Les Briselune\nOn prête à Freya une grande sagesse, une capacité d'écoute, un amour des astres et du savoir. Elle apporte au château son axe vertical et son élan vers l'avenir.\n\nElle fait ériger une tour d'astronomie, mince et solide comme une flèche de pierre, véritable ouverture sur l'insondable et fenêtre vers l'avenir.\n\nMais Freya ne se contente pas d'observer le ciel. Elle fait entrer le monde dans le château en y accumulant des livres, en collectant récits et savoirs anciens. Elle recueille les connaissances comme des graines, non pour les enfermer, mais pour les faire germer.\n\nElle devient la première professeure à transformer l'erreur en apprentissage et à enseigner aux autres comment regarder une étoile. Petite en apparence, immense par sa puissance.\n\nL'héritage des quatre fondateurs\nHavengard n'est pas une simple somme de pierres et de bâtiments. C'est l'union de quatre fonctions vitales : la chaleur d'un foyer, la sécurité d'un refuge, la confiance du savoir et l'ouverture vers le monde.\n\nChacun des fondateurs a donné une partie de lui-même au château. C'est cette union qui lui a permis de devenir bien plus qu'une école : un véritable refuge pour les générations à venir.","details":[]},{"id":"nivara-vervenin","title":"Nivara Vervenin","type":"Fondatrice de la maison Vervenin","summary":"Née au Ghana au Xe siècle, Nivara survit à la destruction de son village, apprend à maîtriser sa magie dans un temple et se lie à un Nagril. Après avoir tenté d’enseigner aux enfants rejetés, elle perd ses élèves et son compagnon, puis poursuit son idéal dans la vallée d’Havengard. Son héritage est la protection des siens et la transmission du savoir.","content":"Fondatrice de la maison Vervenin\n\nL'histoire de Nivara Vervenin est celle du courage, de l'amitié et d'une détermination sans faille. Née au Ghana au Xe siècle, elle deviendra l'une des sorcières les plus puissantes de son époque.\n\nDès son enfance, Nivara possède un don magique exceptionnel. Pourtant, à cette époque, la magie n'est pas acceptée par tous. Dans son village, elle comprend rapidement qu'elle doit dissimuler ses pouvoirs pour éviter d'attirer l'attention des villages voisins. Au lieu d'apprendre à maîtriser sa magie, elle apprend à la cacher.\n\nMais un jour, alors qu'elle pratique en secret, un jeune garçon la surprend. Le lendemain, son village est attaqué et son peuple exterminé. Nivara est la seule survivante. Contrainte de fuir pour sauver sa vie, elle entame une longue période de solitude et de survie.\n\nAprès plusieurs semaines à traverser le désert sans destination, elle découvre un ancien temple de pierre isolé. C'est là que commence une nouvelle vie. Pour la première fois, elle peut pratiquer librement la magie, apprendre à comprendre son don et explorer toutes ses possibilités.\n\nC'est également là qu'elle rencontre un Nagril, une créature recouverte d'écailles. D'abord terrifiée, Nivara craint d'être attaquée, mais la créature ne lui montre aucune hostilité. Au fil des semaines, une relation particulière se développe. Ils apprennent à se comprendre sans même avoir besoin de parler et deviennent de véritables compagnons. Le Nagril représente alors bien plus qu'un simple compagnon : il incarne la confiance, l'amitié et l'accompagnement.\n\nAprès plusieurs mois d'entraînement, Nivara atteint une maîtrise exceptionnelle de la magie. Mais elle n'oublie jamais son passé. Refusant de garder ses connaissances pour elle, elle décide de les transmettre aux enfants rejetés pour leurs pouvoirs, afin de leur offrir un endroit où apprendre librement, sans honte ni peur.\n\nMalheureusement, les peuples voisins restent hostiles et finissent par unir leurs forces pour attaquer Nivara et ses élèves. Au cours de cette tragédie, elle perd tous ceux qu'elle avait protégés, ainsi que son fidèle Nagril. Dévastée, elle reprend le chemin de l'exil.\n\nPourtant, malgré toutes ces épreuves, Nivara refuse d'abandonner. Son voyage la conduit finalement dans la vallée d'Havengard, un lieu qui changera définitivement son destin. Elle y trouvera l'occasion de concrétiser son idéal : offrir aux jeunes sorciers un refuge où ils pourront apprendre et grandir sans jamais avoir à cacher leur nature.\n\nLes traits des Vervenin :\nRusés, stratégiques, ambitieux, déterminés, subtils et discrets. Les Vervenin sont également profondément loyaux envers leurs alliés.\n\nHéritage :\nNivara Vervenin incarne la volonté de protéger les siens, la transmission du savoir et la détermination à ne jamais laisser les autres subir les mêmes injustices que soi.","details":[]},{"id":"freya-briselune","title":"Freya Sveid Briselune","type":"Fondatrice de la maison Briselune","summary":"Née en Islande en 922, Freya grandit au milieu des hivers rigoureux et explore son île en la cartographiant. Après avoir découvert la vallée d’Havengard, elle participe à la fondation du château et de l’école. Briselune reflète sa quête du savoir, son intuition et son indépendance d’esprit ; son emblème est un hibou argenté sous une lune brisée.","content":"Fondatrice de la maison Briselune\n\nOrigines et jeunesse :\n\nNée en 922 après J.-C. dans un petit village islandais, Freya Sveid Briselune grandit dans un environnement rude, marqué par des hivers interminables et des conditions de vie difficiles. Malgré la perte de son frère, elle développe très tôt une profonde passion pour son île et ses mystères.\n\nCurieuse de nature, elle consacre une grande partie de son temps à explorer son territoire et à en dessiner des cartes, cherchant à en percer tous les secrets. Cette soif de découverte et de connaissance deviendra l'un des fondements de sa personnalité.\n\nLa découverte d'Havengard :\n\nAu cours de ses explorations, Freya découvre la vallée d'Havengard. Cette découverte marque un tournant majeur dans son existence. C'est également là qu'elle rencontre les trois autres fondateurs, des rencontres qui changeront sa vie à jamais.\n\nEnsemble, ils donneront naissance au château d'Havengard et à son école, un lieu destiné à accueillir et instruire les jeunes sorciers.\n\nLa fondation de Briselune :\n\nFreya fonde la maison Briselune autour de valeurs qui lui sont chères : la sagesse, la quête du savoir et l'indépendance d'esprit.\n\nElle considère que la connaissance ne repose pas uniquement sur l'efficacité ou l'accumulation de faits, mais également sur l'intuition, l'observation et la capacité à comprendre ce qui échappe au regard ordinaire.\n\nValeurs de Briselune :\nLa quête permanente du savoir.\nL'intuition éclairée.\nL'indépendance d'esprit.\n\nSymbole :\nUn hibou argenté sous une lune brisée. Ce symbole incarne la recherche constante de la lumière dans l'obscurité, ainsi que la capacité à voir au-delà des apparences.\n\nTraits de caractère des Briselune :\n\nCurieux, visionnaires et observateurs, les Briselune savent associer intuition et analyse. Indépendants d'esprit, ils ne se laissent pas facilement influencer. Discrets mais influents, ils ne recherchent pas la reconnaissance et préfèrent laisser leurs connaissances et leurs actions parler pour eux.\n\nDirection de la maison :\nDirecteur : Monsieur Vandbraken.\nDirectrice adjointe : Miss Robin.","details":[]},{"id":"ginsei-rongebois","title":"Ginsei Rongebois Tamanegui","type":"Fondateur de la maison Rongebois","summary":"Après son enlèvement et la perte de son lien sensoriel aux énergies, Ginsei retrouve un chemin vers la nature par la peinture, grâce à son oncle Hiroo. Ses œuvres deviennent un moyen de communiquer avec la magie. Il transmet son art aux oubliés et fonde Rongebois autour de la persévérance, de l’entraide et de la loyauté.","content":"Origines et histoire\nNé dans la banlieue de Tokyo, Ginsei est issu d'une famille proche de l'empereur, suscitant jalousie et méfiance. On murmurait que son clan possédait le pouvoir de contrôler les éléments et de communiquer avec les esprits.\n\nPlus jeune membre du clan, Ginsei était un enfant lumineux et rêveur, profondément connecté à la nature. Il passait ses journées pieds nus dans le jardin, communiant avec la terre, les plantes et les animaux.\n\nSa vie bascula lorsqu'il fut enlevé par un clan rival. Torturé et les pieds brûlés, il perdit sa capacité à ressentir les énergies. Rejeté par les siens après cette épreuve, il sombra dans la solitude. L'enfant solaire avait perdu sa lumière.\n\nSon oncle Hiroo fut le seul à lui tendre la main. Il lui offrit un pinceau et lui enseigna que l'art pouvait devenir un nouveau moyen de communiquer avec la nature.\n\nPeu à peu, en peignant, Ginsei retrouva son énergie vitale. Son pinceau devint le prolongement de son âme et lui permit de retrouver sa maîtrise magique.\n\nSes œuvres prenaient vie et sa renommée grandit jusqu'à ce que les nobles de Kyoto se disputent ses services. Pourtant, il préféra aider les oubliés et les marginaux, leur enseignant la beauté de l'art et l'écoute de la nature.\n\nEn quête de sagesse, il quitta Kyoto pour un long voyage. Il rencontra d'autres âmes errantes dont il fit ses disciples, jusqu'à ce que son périple le conduise dans la vallée d'Havengard.\n\nPhilosophie de Rongebois\nLa maison Rongebois repose sur trois piliers :\nPersévérance : Ne jamais abandonner face aux épreuves.\nEntraide : Avancer ensemble et soutenir les autres.\nLoyauté : Rester fidèle à ceux qui nous font confiance.\n\nRongebois devint un refuge pour tous ceux qui avaient été sous-estimés ou rejetés.\n\nSymbole\nLe castor, symbole de travail, de solidarité et de persévérance.\n\nTraits des membres\nEntraide, solidarité, bienveillance, loyauté, travail, persévérance, humilité et modestie.\n\nIl etait un des sorciers les plus puissant de l'histoire il réussis a faire communiquer magie et art","details":[]},{"id":"aldaric-lonbrasier","title":"Aldaric Temelfort Lonbrasier","type":"Fondateur de la maison Lonbrasier","summary":"Héritier d’un clan français de mercenaires maîtres du feu, Aldaric devient général à vingt ans. Il refuse un ordre qui aurait conduit au massacre d’un village et retourne sa puissance contre son armée, ce qui lui vaut l’exil. À Havengard, il choisit de bâtir et de transmettre ; Lonbrasier s’appuie sur la loyauté, le sacrifice et la bravoure.","content":"Son histoire nous ramène dans la France du Xe siècle.\n\nLes Temelfort formaient un puissant clan de mercenaires français. Ils ne servaient aucun maître en particulier et vendaient leur puissance aux seigneurs du royaume. Au fil des conflits, ils accumulèrent richesse et influence. Leur plus grande force résidait dans leur maîtrise de la magie du feu, un savoir ancestral qu'ils gardaient jalousement secret. La famille avait construit toute son identité autour de cette magie destructrice.\n\nC'est dans cet environnement strict, marqué par le combat, la stratégie et la discipline, qu'Aldaric grandit. Il se démarquait de ses frères et sœurs par son intelligence et ses talents exceptionnels en magie. Pourtant, contrairement aux attentes de sa famille, il ne rêvait pas de détruire, mais de créer.\n\nÀ seulement 20 ans, il devint général et remporta plusieurs campagnes victorieuses. Sa réputation dépassa rapidement les frontières françaises. Mais son succès suscita autant d'admiration que de crainte, y compris au sein de son propre clan.\n\nUn jour, il reçut l'ordre d'attaquer un village. Mal renseignée, son armée s'apprêtait à massacrer des innocents. Déchiré entre son devoir et ses convictions, Aldaric prit une décision irréversible : il refusa l'ordre et retourna sa puissance contre sa propre armée ainsi que contre son oncle, responsable de l'attaque. Cet acte brisa définitivement ses liens avec sa famille.\n\nJugé pour sa trahison, il échappa à la peine de mort, mais fut condamné à l'exil. Isolé, rongé par les remords et le sentiment de perte, il erra longtemps, loin de la guerre et des siens.\n\nAprès une longue période de solitude, il découvrit une vallée paisible : Havengard. Il y vit l'occasion d'un nouveau départ et d'une rédemption. Sans avoir perdu ses talents, il décida de bâtir un lieu où transmettre ses connaissances et ses valeurs plutôt que de les utiliser pour détruire.\n\nC'est ainsi que son histoire rejoignit celle des autres fondateurs d'Havengard. Il fonda la maison des Lonbrasier, guidée par trois valeurs fondamentales : la loyauté, le sacrifice et la bravoure.\n\nSymbole de la maison : le phoenix","details":[]},{"id":"souffle-origines-du-monde","title":"Le Souffle : l’origine du monde","type":"Cosmogonie","summary":"Selon ce récit, le Souffle est à l’origine des éléments et de la magie. L’Ombre et la Lumière font naître le Temps, puis apparaissent la Terre, le Feu, l’Eau et l’Air. Lorsque des humains tentent de soumettre le Souffle, des catastrophes provoquent la chute de la première humanité et la séparation entre Porteurs du Souffle et Golmus. Leur reconstruction commune devient la Première Alliance.","content":"L'origine du monde\nLe Souffle n'était pas un être vivant. Il n'appartenait à personne et ne répondait à aucune volonté. Il circulait, tout simplement. Il traversait chaque chose, reliait les éléments entre eux et était présent partout dans le monde.\n\nAvec le temps, le Souffle donna naissance aux éléments.\n\nLa première séparation fut celle de l'Ombre et de la Lumière. Deux forces opposées, mais toutes deux indispensables à l'équilibre du monde. Leur alternance créa un rythme, et de ce rythme naquit le Temps.\n\nPuis, le Souffle se transforma en matière, donnant naissance à la Terre. Celle-ci façonna le monde : les montagnes, les plaines et les reliefs qui composent sa surface.\n\nEnsuite apparut le Feu, porteur de chaleur et de transformation.\n\nVint alors l'Eau, qui donna naissance aux rivières, aux pluies, aux brumes et aux océans.\n\nEnfin apparut l'Air, qui remplit les espaces laissés libres par la matière. Il transporte les sons, les parfums et les mouvements. Il permet aux choses de circuler et de se rencontrer.\n\nAinsi naquit le monde, façonné par les différentes manifestations du Souffle.\n\nLa naissance de la magie\nLa magie est ce qui circule entre les éléments et les relie les uns aux autres. Elle trouve son origine dans le Souffle.\n\nElle n'est pas simplement un outil que l'on utilise ou une force que l'on commande. Elle fait partie intégrante du monde. Elle est présente dans chaque élément, dans chaque mouvement et dans chaque lien qui unit les choses.\n\nLorsque les premiers humains apparurent, certains furent capables de ressentir le Souffle et d'entrer en harmonie avec lui.\n\nAu début, ils l'utilisaient pour des choses simples : se protéger, survivre, faciliter leur quotidien et aider leur prochain. Ils ne cherchaient pas à le posséder, mais simplement à vivre avec lui.\n\nLa chute de la première humanité\nAvec le temps, certains humains commencèrent à vouloir imposer leur volonté au Souffle. Ils ne se contentaient plus de l'accompagner : ils cherchaient à le contrôler, à le soumettre et à se l'approprier.\n\nLe monde connut alors de profonds bouleversements. Le Souffle, trop sollicité et malmené, provoqua de grandes catastrophes naturelles. L'équilibre qui avait permis au monde de naître fut ébranlé.\n\nCes événements entraînèrent la chute de la première humanité.\n\nLes survivants durent alors apprendre à vivre dans un monde profondément changé. Ils se retrouvèrent divisés en deux groupes.\n\nLes Porteurs du Souffle et les Golmus\nLes premiers étaient ceux qui n'avaient pas abusé du Souffle. Leur lien avec lui était toujours présent et ils étaient encore capables de le ressentir. On les appela les Porteurs du Souffle.\n\nLes seconds avaient perdu ce lien. Leur connexion au Souffle s'était refermée et la magie ne leur répondait plus. On les appela les Golmus.\n\nPrivés de magie, les Golmus apprirent à bâtir autrement. Ils développèrent leur savoir-faire, utilisèrent leurs mains et façonnèrent des outils. Ils apprirent à construire, à travailler et à vivre sans dépendre du Souffle.\n\nPeu à peu, les deux peuples apprirent à cohabiter. Ils comprirent que leurs différences n'étaient pas une faiblesse, mais pouvaient devenir une force.\n\nCette période de reconstruction et de coopération fut appelée la Première Alliance.","details":[]},{"id":"oniromancie","title":"L’Oniromancie","type":"Divination","summary":"L’oniromancie, ou interprétation des rêves, serait née d’une légende draconique liée à Eryn Dhalys. Elle distingue les rêves naturels, influencés et prophétiques, ces derniers ne présentant que des possibilités. À Havengard, l’enseignement reste théorique ; toute pratique exige une licence. Les rêves ne doivent jamais être forcés, les interprétations ne sont pas des vérités définitives et il est interdit d’intervenir dans le rêve d’autrui.","content":"Oneiros : rêve — Manteia : divination\n\nOrigines et légende\nSelon une ancienne légende draconique, l'oniromancie serait née grâce à Eryn Dhalys, un dragon ancestral surnommé « Le Premier Souffle des Songes ».\n\nEryn Dhalys ne parlait jamais. Il était considéré comme un pont entre la réalité et toutes les possibilités qui n'avaient pas encore pris forme. Les êtres primordiaux ne connaissaient pas encore les rêves, jusqu'au jour où ce dragon s'endormit pour la première fois. Ses songes apparurent alors dans le ciel, sous forme de mystérieux reflets.\n\nPour la première fois, la magie semblait leur parler. Un jeune dragon, intrigué, s'approcha de l'un de ces reflets et le toucha. Il fut alors projeté dans le rêve d'Eryn Dhalys, où il découvrit des messages provenant du passé.\n\nIl comprit que les rêves pouvaient renfermer des connaissances, des souvenirs et peut-être même des fragments de l'avenir. Selon la tradition draconique, ce fut la première interprétation des rêves de l'histoire. Les dragons conclurent alors un pacte afin de protéger et d'interpréter ces visions.\n\nAinsi serait née l'oniromancie.\n\nCette histoire reste toutefois une légende, dont l'authenticité n'a jamais été vérifiée.\n\nPrincipes de l'oniromancie\nL'oniromancie est l'art d'interpréter les rêves. Cependant, tous les rêves ne sont pas prophétiques. Certains sont influencés par la magie, tandis que d'autres peuvent contenir des fragments d'événements futurs.\n\nSon rôle est de distinguer ces différentes manifestations. Une interprétation n'est jamais universelle et aucun rêve ne possède une signification systématique.\n\nOn distingue trois catégories de rêves :\n\nLes rêves naturels : les plus courants, ils sont liés au quotidien et ne possèdent aucune propriété divinatoire.\nLes rêves influencés : modifiés par des éléments magiques, comme des potions ou des résidus magiques.\nLes rêves prophétiques : extrêmement rares et délicats à interpréter, ils peuvent contenir des fragments de ce qui pourrait arriver. Ils représentent des possibilités, jamais des certitudes.\n\nEnseignement et éthique à Havengard\nConsidérée comme la plus ancienne et la plus fondamentale des sept écoles de divination, l'oniromancie exige patience et discernement. Ce sont des qualités indispensables pour la suite de vos études.\n\nÉtudier la divination ne signifie pas être autorisé à la pratiquer. À Havengard, seuls les fondements théoriques de cette discipline sont enseignés. Toute pratique nécessite une licence délivrée par l'autorité compétente.\n\nUne mauvaise interprétation peut profondément bouleverser, voire gâcher la vie d'une personne. C'est pourquoi trois principes éthiques fondamentaux doivent être respectés :\n\nUn rêve ne doit jamais être forcé.\nUne interprétation ne doit jamais être considérée comme une vérité définitive.\nIl est strictement interdit d'intervenir dans le rêve d'une autre personne.","details":[]},{"id":"constitution-sorcier","title":"La constitution d’un sorcier","type":"Physiologie magique","summary":"La magie circule dans l’organisme des sorciers et soutient leur métabolisme, leur résistance et leurs capacités. Leur espérance de vie atteint environ 150 ans, mais un déclin progressif commence souvent vers 130 ans. Repos, entraînement mesuré et équilibre mental aident à préserver leur santé.","content":"La magie ne se limite pas à l’utilisation d’une baguette. Elle fait partie intégrante de chaque sorcier et circule en permanence dans son organisme, influençant aussi bien son corps que son esprit et sa résistance générale.\n\nCette particularité biologique leur confère plusieurs avantages : un ralentissement du vieillissement, un métabolisme renforcé, une meilleure résistance aux maladies ainsi qu’une capacité à canaliser la magie sur de longues périodes.\n\nLa plupart des sorciers possèdent une espérance de vie d’environ 150 ans, contre 80 à 90 ans pour les Golmus.\n\nVIEILLISSEMENT ET DÉCLIN MAGIQUE\nLongévité ne signifie pas immortalité. À partir de 130 ans environ, l’organisme et les capacités magiques d’un sorcier commencent progressivement à décliner.\n\nLa récupération devient plus lente, la fatigue survient plus rapidement et canaliser la magie demande davantage d’efforts. La magie reste présente, mais son utilisation devient plus éprouvante.\n\nCe déclin varie selon les individus et dépend de plusieurs facteurs, notamment leur constitution, leur mode de vie et leur expérience magique.\n\nENTRETENIR SA CONSTITUTION\nPour préserver son équilibre physique et magique, un sorcier doit veiller à adopter de bonnes habitudes :\n• Le repos : accorder à son organisme suffisamment de temps pour récupérer.\n• La pratique magique : maintenir un entraînement régulier et mesuré.\n• L’équilibre mental : préserver sa stabilité émotionnelle et psychologique.\n• Les potions de soutien : les utiliser de manière raisonnée et adaptée à ses besoins.\n\nLES DANGERS POUR L’ORGANISME\nCertaines pratiques peuvent mettre sérieusement en danger la constitution d’un sorcier :\n• Enchaîner les sortilèges sans période de repos.\n• Ignorer les premiers signes de fatigue magique ou physique.\n• Consommer des potions sans encadrement approprié.\n• Pratiquer des magies instables ou interdites.\n\nCes comportements peuvent entraîner un épuisement de l’organisme et perturber son équilibre magique.\n\nPARTICULARITÉ BIOLOGIQUE\nLa principale particularité du sorcier réside dans la présence constante de magie au sein de son organisme. Elle participe à son fonctionnement et influence directement ses capacités physiques et mentales.\n\nRègle fondamentale : apprendre à reconnaître ses limites et à les respecter est indispensable pour préserver sa santé et maîtriser durablement sa magie.","details":[{"label":"Espérance de vie des sorciers","value":"Environ 150 ans"},{"label":"Espérance de vie des Golmus","value":"80 à 90 ans"},{"label":"Début du déclin","value":"Vers 130 ans"}]}],"alchimie":[{"id":"poudre-cornelongue","title":"Poudre Cornelongue","type":"Ingrédient alchimique","summary":"Poudre violette aux reflets dorés, issue de cornes de créatures magiques. Elle agit sur la croissance des cheveux et de la pilosité ; sa grande finesse et ses effets imposent de la manipuler avec prudence.","content":"Nom latin : Pulbis Cornelungi\n\nApparence\nPoudre d’un violet profond aux magnifiques reflets dorés. Chaque grain semble scintiller dans une fiole et peut produire une douce lueur. Dans l’obscurité, ses reflets donnent presque l’impression que la poudre danse. Certains la comparent à une poussière d’étoile.\n\nAttention : une belle apparence ne signifie pas que l’ingrédient est inoffensif. Elle est extrêmement fine et si légère qu’un simple souffle peut la mettre en suspension. Il faut donc la conserver dans un récipient adapté.\n\nOdeur\nMélange de métal froid et d’air chargé d’orage. Certains y reconnaissent également des notes minérales rappelant la pierre.\n\nPropriétés\nLorsque la poudre entre en contact avec un liquide, elle se dissout rapidement. Elle agit principalement sur la croissance capillaire et la pilosité. Dans certaines préparations, elle ralentit la pousse ; dans d’autres, elle provoque la chute. Certaines potions peuvent contribuer à annuler des modifications physiques. Elle n’est pas une solution universelle à toutes les métamorphoses, mais concerne surtout ce qui touche à la pilosité. Son utilisation nécessite une extrême prudence.\n\nOrigine\nCe n’est pas une plante. Elle provient des cornes de créatures magiques, notamment des sangliers d’Havengard. Ces sangliers boivent de l’eau de pureté qui influence leurs défenses. On peut les récolter de l’autre côté du lac de la ville.\n\nRisques\n• Perte excessive de pilosité, temporaire ou durable.\n• Démangeaisons ou irritations.\n• Atteinte temporaire d’autres tissus corporels.\n\nUne potion qui modifie l’apparence d’une personne ne doit pas être utilisée sans son consentement.\n\nConservation\nFlacon hermétique et magiquement scellé. Une exposition à l’air ou à la lumière peut diminuer ses propriétés magiques. En alchimie, le stockage des ingrédients est aussi important que leur préparation.\n\nNote\nCette poudre provient de matière animale. Sa récolte ne concerne pas les élèves de première année.","details":[{"label":"Nom latin","value":"Pulbis Cornelungi"},{"label":"Origine","value":"Cornes de créatures magiques, notamment des sangliers d’Havengard."}]},{"id":"melorine","title":"La Mélorine","type":"Plante aquatique · Ingrédient alchimique","summary":"Plante aquatique massive aux reflets émeraude, la Mélorine pousse dans les eaux stagnantes et marécageuses. Récoltée délicatement au lever du soleil, elle sert notamment aux potions de respiration subaquatique, dont la Nanis d’Humécume.","content":"Nom latin : Alguae Viridissima Melorina\n\nAPPARENCE\nLa Mélorine est une plante aquatique massive, souvent confondue avec une simple algue. Elle est pourtant considérée comme un ingrédient essentiel de l’alchimie, notamment dans la préparation des potions de respiration subaquatique.\n\nElle ressemble à un étrange corail mystique, d’un vert émeraude rappelant la couleur du verre d’eau. Elle flotte à la surface des eaux stagnantes. Sa surface lisse et légèrement ondulée est parsemée de petits points blancs évoquant des spores luminescentes ou des cristaux de sel.\n\nSa couleur dominante se mêle harmonieusement à des nuances de turquoise et de vert d’eau. Des reflets plus clairs semblent émettre une douce lueur, donnant à l’ensemble une apparence ancienne et magique, comme si la plante provenait des profondeurs enchantées.\n\nTEXTURE\nSa surface est gélatineuse et souple, semblable à celle d’une algue fraîche. Sous la pression, elle révèle toutefois une résistance élastique due à ses longues fibres internes. Lorsqu’on la saisit, elle glisse légèrement entre les doigts et laisse une fine pellicule humide rappelant la rosée marine.\n\nSes ramifications possèdent un toucher plus ferme, presque cartilagineux, comme si elles étaient habituées à supporter les lentes pulsations de la magie aquatique qui les traverse.\n\nODEUR\nSon parfum discret mais persistant mêle douceur aquatique et notes minérales. On y retrouve l’odeur de la pluie tombant sur des pierres chaudes, enrichie d’une nuance saline rappelant les marais tranquilles juste avant l’aube.\n\nCertains alchimistes affirment même percevoir une légère note d’ozone, semblable à un écho des courants magiques, donnant à son odeur une fraîcheur ancienne, presque cérémoniale.\n\nHABITAT\nOn trouve la Mélorine dans les eaux peu profondes et stagnantes, voire marécageuses, particulièrement autour des vieilles pierres et des bois immergés.\n\nÀ maturité, elle développe une particularité singulière : elle peut vivre aussi bien dans son milieu aquatique qu’à l’air libre.\n\nRÉCOLTE\nMoment idéal : la récolte doit s’effectuer au lever du soleil, lorsque les premières lueurs caressent encore la surface des eaux calmes. C’est à cet instant que la plante libère de petites bulles translucides, signe que son essence a atteint sa pleine maturité.\n\nCes bulles disparaissent dès que la lumière devient trop vive. Plus tard dans la journée, la plante se referme sur elle-même et perd toute valeur alchimique.\n\nMéthode : il est recommandé d’utiliser un filet de soie enchanté ou une spatule de nacre. La récolte exige une extrême délicatesse : tout contact avec des surfaces métalliques rugueuses risque d’endommager ses fibres. Certains herboristes prennent même soin de plonger leurs mains dans de l’eau bénite avant la cueillette.\n\nCONSERVATION\nUne fois récoltée, la Mélorine doit être immédiatement immergée dans de l’eau distillée ou de l’eau lunaire afin de préserver ses propriétés alchimiques.\n\nUTILISATION MAGIQUE\nLa Mélorine est principalement utilisée dans la préparation de potions liées à la respiration subaquatique, notamment la Nanis d’Humécume.","details":[{"label":"Nom latin","value":"Alguae Viridissima Melorina"},{"label":"Habitat","value":"Eaux peu profondes et stagnantes, milieux marécageux"},{"label":"Récolte","value":"Au lever du soleil, lorsque des bulles translucides apparaissent"}]},{"id":"racine-herbecorce","title":"La Racine d’Herbecorce","type":"Racine magique · Ingrédient alchimique","summary":"Racine noueuse des régions côtières, l’Herbecorce produit une sève qui aide le corps à respirer sous l’eau et dans certains milieux irrespirables. Indispensable à plusieurs potions de survie, elle ne soigne aucune maladie.","content":"Nom latin : Radix Harboris Humilis\n\nAPPARENCE ET CARACTÉRISTIQUES\nLa Racine d’Herbecorce ressemble à une vieille racine abandonnée dans la terre. Ne vous fiez pourtant pas à son apparence : elle possède une propriété exceptionnelle qui permet de respirer dans des environnements normalement irrespirables, comme sous l’eau ou dans certains mondes éthérés, notamment la Forêt des Brumes.\n\nC’est un ingrédient particulièrement précieux pour les potionistes. Certains explorateurs considèrent même cette racine comme leur assurance-vie.\n\nNoueuse, spiralée et fripée, elle peut atteindre jusqu’à 40 cm de longueur. Sa couleur est généralement brunâtre, mais peut tirer vers le vert foncé ou le jaune selon l’humidité du sol.\n\nSa surface extérieure est rugueuse, tandis que son intérieur est très dense, fibreux et légèrement visqueux lorsqu’on l’incise.\n\nElle dégage une forte odeur de terre humide et d’écorce moisie, parfois accompagnée d’une légère note sucrée.\n\nAttention : toute la racine ne possède pas la même valeur alchimique. C’est principalement sa partie centrale qui concentre les substances responsables de ses propriétés magiques.\n\nHABITAT\nElle apprécie particulièrement les régions côtières, les falaises maritimes et les endroits régulièrement balayés par les embruns. Elle pousse dans des sols riches et bien aérés, là où l’humidité et la lumière du soleil se rencontrent.\n\nRÉCOLTE\nMoment idéal : juste avant l’aube, lorsque sa sève respiratoire atteint sa plus forte concentration et que son énergie magique est à son apogée.\n\nMéthode : la récolte nécessite des gants. Il faut détacher délicatement la racine à la main, en la berçant doucement pour la libérer du sol. Il ne faut surtout pas tirer brutalement dessus, au risque de tuer la plante et d’empêcher sa régénération.\n\nCONSERVATION\nLa racine doit être conservée avec précaution. On peut l’immerger dans une boue enchantée ou l’envelopper dans un tissu de mousse humide. La lumière et l’exposition à l’air altèrent rapidement ses propriétés magiques.\n\nRISQUES ET PRÉCAUTIONS\nUn mauvais dosage de la Racine d’Herbecorce peut provoquer des cauchemars liés à la noyade et à l’asphyxie.\n\nNe pas confondre avec l’Ombrehecorce, qui provoque un gonflement des bronches pouvant être fatal.\n\nNe jamais chauffer cette racine à sec : elle dégagerait des odeurs nauséabondes susceptibles d’attirer des créatures souterraines qui apprécient la magie organique.\n\nPROPRIÉTÉS ET UTILISATIONS MAGIQUES\nSa principale particularité réside dans sa sève visqueuse. Une fois préparée et ingérée, celle-ci forme une membrane semi-perméable à l’intérieur du corps. Cette membrane magique filtre certains éléments de l’environnement et permet notamment de transformer des substances comme l’eau, la brume et certaines vapeurs en air respirable.\n\nCette capacité rend la Racine d’Herbecorce indispensable à de nombreuses potions de survie. On la retrouve notamment dans :\n• La Nanis d’Humécume.\n• Le Souffle d’Aelyne.\n• Le Ragoût du Veilleur.\n\nElle peut également être séchée puis réduite en poudre pour faciliter son utilisation dans certaines préparations.\n\nUTILISATION CULINAIRE\nLa Racine d’Herbecorce possède également une fonction culinaire. Elle entre notamment dans la préparation du Ragoût du Veilleur, un plat à base de racine et de lait, apprécié pour son caractère nourrissant et consistant.\n\nÀ retenir : la Racine d’Herbecorce est un ingrédient de maintien et de survie. Elle ne soigne pas et ne guérit aucune maladie : elle permet simplement à un individu de survivre dans un environnement qui lui serait normalement fatal.","details":[{"label":"Nom latin","value":"Radix Harboris Humilis"},{"label":"Longueur","value":"Jusqu’à 40 cm"},{"label":"Récolte","value":"Juste avant l’aube"},{"label":"Usage","value":"Potions respiratoires et Ragoût du Veilleur"}]},{"id":"baie-mandragore","title":"Baie de Mandragore","type":"Fruit magique · Ingrédient alchimique","summary":"Petit fruit rouge issu des buissons de mandragore adultes. Ses propriétés curatives en font un ingrédient polyvalent pour de nombreuses potions, mais un mauvais dosage ou une préparation incorrecte peut provoquer un engourdissement ou une paralysie temporaire.","content":"Nom latin : Bakaé mandragoraé\n\nDESCRIPTION\nPetit fruit au potentiel considérable, la baie de Mandragore pousse sur les buissons de mandragore adultes. Reconnue pour ses nombreuses propriétés curatives, elle occupe une place importante dans l’arsenal des herboristes.\n\nAPPARENCE ET TEXTURE\nDe la taille d’une bille, pouvant atteindre celle d’une noisette, elle présente une couleur rouge vif qui vire au bordeaux à maturité. Sa texture est croquante et juteuse, avec une chair filandreuse renfermant en son centre un noyau poudreux.\n\nODEUR ET GOÛT\nElle dégage un parfum subtil et singulier, frais, rappelant la terre humide après la pluie. Lorsqu’on l’écrase, une légère effluve herbacée s’en dégage. Son goût est doux et herbacé.\n\nHABITAT\nElle pousse principalement en bordure des potagers enchantés ou dans les serres spécialisées, à proximité des buissons de mandragore adultes.\n\nRÉCOLTE\nLe lever du jour constitue le moment idéal pour sa récolte, lorsque les fruits sont encore imprégnés de la fraîcheur nocturne.\n\nUTILISATIONS\nAvant tout reconnue comme un ingrédient curatif, la baie de Mandragore entre dans la fabrication de nombreuses potions. Ses applications vont des soins capillaires aux breuvages les plus complexes, notamment ceux permettant des transformations polymorphiques. Ses propriétés ne se limitent donc pas à la guérison physique et offrent de nombreuses possibilités en alchimie.\n\nEFFETS SECONDAIRES\nMalgré ses vertus, une mauvaise préparation ou un dosage inadapté peut provoquer un engourdissement, voire une paralysie temporaire.\n\nCONCLUSION\nPetit fruit aux propriétés remarquables, la baie de Mandragore est un ingrédient précieux pour tout herboriste. Sa polyvalence et ses capacités curatives en font une ressource particulièrement recherchée.","details":[{"label":"Nom latin","value":"Bakaé mandragoraé"},{"label":"Habitat","value":"Potagers enchantés et serres spécialisées"},{"label":"Récolte","value":"Au lever du jour"}]},{"id":"rosimence","title":"Rosimence","type":"Plante herbacée toxique · Ingrédient alchimique","summary":"Plante majestueuse pouvant atteindre trois mètres, la Rosimence fournit un ingrédient précieux pour l’herboristerie avancée. À l’état brut, elle est extrêmement toxique : sa sève peut paralyser et ses vapeurs provoquer une transe prolongée.","content":"Nom latin : Floralis coralium mortifera\n\nDESCRIPTION\nPlante herbacée majestueuse pouvant atteindre 3 mètres. Son tronc robuste et ses tiges charnues et rigides sont recouverts de petites roses imbriquées les unes dans les autres. À la lumière, sa surface semble vibrer comme si un cœur végétal battait en son sein. Sa couleur varie du rose pastel au violet profond selon la lumière et l’humidité. Sa texture spongieuse et tiède rappelle le corail desséché, mais semble étrangement vivante au toucher.\n\nODEUR\nParfum léger de rose mêlé à des notes salines, évoquant la brume d’un matin d’été dans un jardin fleuri. Elle attire particulièrement les animaux à l’odorat sensible.\n\nHABITAT\nElle pousse dans les zones tropicales enchantées, nourrie par les embruns des vagues. Cultivée en jardin, elle perd progressivement ses propriétés magiques et une partie de sa toxicité.\n\nRÉCOLTE ET CONSERVATION\nLe crépuscule et la pleine lune sont les seuls moments où sa toxicité diminue. Les pétales doivent être cueillis avec une pince en argent trempée dans une solution lunaire, puis immédiatement plongés dans un bain neutralisant à base d’eau pure. Tout contact direct est dangereux : sa sève pénètre la peau et provoque un engourdissement. Conservation obligatoire dans un bocal en cristal hermétique afin de préserver ses propriétés et contenir ses effluves.\n\nUTILISATIONS MAGIQUES\nIngrédient précieux en herboristerie avancée, elle entre dans la composition de diverses potions. Elle est réputée pour restaurer la clarté mentale et faciliter l’accès aux zones protégées par des brumes ensorcelées. Ses autres applications restent nombreuses et parfois méconnues.\n\nTOXICITÉ ET PRÉCAUTIONS\nÀ l’état brut, elle est extrêmement toxique. Sa sève peut provoquer engourdissement, paralysie, délire et, dans les cas graves, la mort. Ne jamais la brûler : ses vapeurs hallucinogènes peuvent induire une transe prolongée. Tenir éloignée des animaux domestiques. Toute manipulation exige des gants, un masque et des protections magiques mineures.","details":[{"label":"Nom latin","value":"Floralis coralium mortifera"},{"label":"Taille","value":"Jusqu’à 3 mètres"},{"label":"Précaution","value":"Toxique à l’état brut; ne jamais brûler"}]},{"id":"larme-chrysalide","title":"Larme de Chrysalide","type":"Ingrédient alchimique · Préparation de l’eau de tristesse","summary":"Goutte bleue, fluide et légèrement visqueuse, la Larme de Chrysalide est récoltée avant sa transformation en eau de tristesse. Elle ne doit pas être confondue avec la préparation finale ni consommée sans autorisation.","content":"TYPE\nIngrédient alchimique utilisé dans la préparation de l’eau de tristesse.\n\nDESCRIPTION\nLa Larme de Chrysalide est un ingrédient servant à préparer l’eau de tristesse. Elle constitue la matière première de cette préparation et possède des caractéristiques visuelles et physiques particulières.\n\nAPPARENCE\nLa larme se présente sous la forme d’une goutte d’eau. Elle possède une couleur bleue caractéristique, dont les reflets constituent le premier élément permettant de l’identifier.\n\nTEXTURE\nFluide et légèrement visqueuse, elle reste liquide, mais présente une consistance plus épaisse que celle de l’eau ordinaire.\n\nGOÛT\nSa saveur est douce, accompagnée d’une légère note acidulée rappelant celle d’un fruit légèrement acide.\n\nTRANSFORMATION MAGIQUE\nLa Larme de Chrysalide est le produit de récolte initial. Après transformation alchimique, elle devient de l’eau de tristesse, reconnaissable à son liquide aux reflets bleus.\n\nIl est important de distinguer les deux appellations :\n• Larme de Chrysalide : ingrédient récolté avant transformation.\n• Eau de tristesse : préparation obtenue après transformation magique.\n\nPRÉCAUTIONS\nMalgré son apparence et son goût relativement agréables, les préparations magiques ne doivent jamais être consommées sans autorisation.","details":[{"label":"Aspect","value":"Goutte bleue"},{"label":"Texture","value":"Fluide et légèrement visqueuse"},{"label":"Transformation","value":"Eau de tristesse"}]}]};
